  const ms = Math.min(Math.max(0, who.exp * 1000 - now), MAX_TIMER_MS);
  const timer = setTimeout(() => {
    try { ws.close(WS_TOKEN_EXPIRED, 'sign-in token expired'); } catch { /* already closing */ }
  }, ms);
  timer.unref?.();
  ws.once('close', () => clearTimeout(timer));
