// ---------------------------------------------------------------------------
// Filesystem browsing for the add-project folder selector. Hybrid picker:
// POST /api/fs/pick-folder opens the native OS dialog (the server runs on the
// user's machine); when it reports `unsupported` the UI falls back to an
// in-app modal fed by GET /api/fs/dirs. Localhost-only like every route here
// (global isLocalRequest middleware).
//
// Hosted (remote mode) with the terminal and actions off, a signed-in person may
// browse, add and install into Worca's own folders only: the projects root and the
// Worca home (<base>/.worca-cc, the data dir), hidden folders below them excluded
// (src/core/fs-scope.mjs). Registered projects do NOT widen this: an entry added before
// the limit existed (even `/`) must not re-open the disk, and hosted projects are cloned
// under the projects root. WORCA_DATA_DIR itself is not a root either: on a single-volume
// host it also holds HOME with Claude Code's login. WORCA_TERMINAL_REMOTE=1 or
// WORCA_ACTIONS_REMOTE=1 already grant more than a listing, so either lifts the limit.
const fsLimitedHere = (req = null) => REMOTE_MODE && !terminalEnabledHere(req) && !actionsEnabledHere(req);
const FS_BROAD_WARNED = new Set();
/** Worca's own folders as real paths: the projects root and the Worca home. While no projects root is configured
 *  (the default <worcaHome>/projects, U6) the roots are TODAY's — the OS home (it WAS the default root; S50 keeps the
 *  hosted Folder-add limit at today's rule) with the Worca home folded into it when it lies there, so the Worca home's
 *  runs/, store/ and settings stay a hidden folder — plus the default projects folder itself once it exists (New and
 *  Clone fill it; fs-scope insideRoots accepts any containing root, so its projects are not "hidden"). A broad one is
 *  skipped (logged once). */
async function fsAllowedRoots() {
  let home = null;
  try { home = worcaHome(); } catch { /* no resolvable home (node:test without WORCA_HOME) */ }
  const onSkip = (c, r) => {
    if (FS_BROAD_WARNED.has(r)) return;
    FS_BROAD_WARNED.add(r);
    console.warn(`[worca-ui] folder browser: ${r} (from ${c}) is too broad to browse on a hosted Worca; skipped. Set WORCA_PROJECTS_ROOT to a deeper folder.`);
  };
  if (projectsRootSource() !== 'default') return realRoots([getProjectsRoot(), home], { onSkip });
  const today = await realRoots([defaultRoot(), home], { onSkip });
  // The folder itself only: a link at <worcaHome>/projects (to store/, or ~/.ssh) must not make its target a root.
  const own = home ? await realOrNull(home) : null;
  const extra = (await realRoots([getProjectsRoot()], { onSkip })).filter((r) => own && r === path.join(own, 'projects') && !insideRoots(r, today));
  return [...today, ...extra];
}
/** True when every path may be used here; otherwise answers 403 FS_OUTSIDE_ALLOWED and returns false. */
async function requireFsAllowed(req, res, paths) {
  if (!fsLimitedHere(req)) return true;
  const roots = await fsAllowedRoots();
  for (const p of paths) {
    if (!p) continue;
    if ((await checkInside(p, roots)).inside) continue;
    res.status(403).json({ error: outsideAllowedMessage(p), code: FS_OUTSIDE_ALLOWED });
    return false;
  }
  return true;
}
// GET answers whether "Choose folder…" can open a native dialog for the viewer, without opening
// one (the Add project dialog no longer asks: it opens on New either way, P2). Never on a hosted worca (the dialog
// would open on the server, not on the viewer's screen).
app.get('/api/fs/pick-folder', (req, res) => {
  res.json({ available: !REMOTE_MODE && nativeDialogAvailable() });
});
app.post('/api/fs/pick-folder', async (req, res) => {
  try {
    // Limited: a native dialog would open on the server with the whole disk in it; the UI
    // falls back to the in-app browser, which stays inside the allowed folders.
    if (fsLimitedHere(req)) return res.json({ status: 'unsupported' });
    // `purpose` only picks the dialog title from a closed set (folder-dialog.mjs);
    // `multiple` (strictly true) asks for a multi-select dialog where the OS has one.
    const purpose = typeof req.body?.purpose === 'string' ? req.body.purpose : undefined;
    const multiple = req.body?.multiple === true;
    res.json(await pickFolderNative({ purpose, multiple }));
  } catch (err) {
    res.status(500).json({ error: err && err.message ? err.message : String(err) });
  }
});

app.get('/api/fs/dirs', async (req, res) => {
  try {
    const roots = fsLimitedHere(req) ? await fsAllowedRoots() : null;
    res.json(await listFolders(typeof req.query.path === 'string' ? req.query.path : '', { roots }));
  } catch (err) {
    if (err && err.code === 'BAD_REQUEST') return badRequest(res, err.message);
    if (err && err.code === FS_OUTSIDE_ALLOWED) return res.status(403).json({ error: err.message, code: FS_OUTSIDE_ALLOWED });
    res.status(500).json({ error: err && err.message ? err.message : String(err) });
  }
});

// ---------------------------------------------------------------------------
// Workspace registry: a named set of 2+ onboarded git repos with one editable
// interconnection description. Thin delegation to src/core/workspaces.mjs (which
// owns validation + persistence); the route maps err.code -> HTTP exactly like
// /api/projects + /api/workflows. The :id is the workspaceKey, validated against
// WORKSPACE_KEY_RE before any disk touch (a stale/crafted id reads as 404).
// ---------------------------------------------------------------------------
/** The automatic re-scan run (autoRescan: started after a member change) that still owns a
 *  workspace, or null — a paused one included (it resumes into the workspace). The page's loader
 *  follows it after a reload, and shows a paused one as paused: its rescan-paused frame is gone. */
function liveAutoRescan(id) {
  for (const r of runs.values()) if (r.workspaceId === id && r.autoRescan && ownsWorkspaceTarget(r)) return r;
  return null;
}
function liveRescanOf(id) {
  const r = liveAutoRescan(id);
  if (!r) return null;
  const out = { runId: r.id, pipelineId: r.pipelineId || null, paused: String(r.status).toLowerCase() === 'paused' };
  // A resumed run's harness reads 'wf_default' until _resume() restores its workflowId (orchestrator.mjs:89,
  // run-harness.mjs:1797): for that moment a partial run lists as a full one — harmless, it self-corrects.
  return r.orch?.workflowId === WORKSPACE_RESYNTH_WORKFLOW_ID ? { ...out, partial: true } : out;
}
const withRescan = (w) => { const rescan = w && liveRescanOf(w.id); return rescan ? { ...w, rescan } : w; };

app.get('/api/workspaces', async (_req, res) => {
  try {
    res.json({ workspaces: (await listWorkspaces()).map(withRescan) });
  } catch (err) {
    res.status(500).json({ error: err && err.message ? err.message : String(err) });
  }
});

app.get('/api/workspaces/:id', async (req, res) => {
  const id = req.params.id;
  if (!WORKSPACE_KEY_RE.test(id)) return res.status(404).json({ error: 'workspace not found' });
  try {
    const workspace = await readWorkspace(id);
    if (!workspace) return res.status(404).json({ error: 'workspace not found' });
    res.json({ workspace: withRescan(workspace) });
  } catch (err) {
    res.status(500).json({ error: err && err.message ? err.message : String(err) });
  }
});

app.post('/api/workspaces', async (req, res) => {
  const body = req.body || {};
  // Normalize member paths through the same single source of truth as /api/run;
  // createWorkspace re-normalizes + de-dupes by canonical root, but a fast <2
  // reject here matches the spec's defense-in-depth (§2.3).
  const projectPaths = Array.isArray(body.projectPaths)
    ? body.projectPaths.map((p) => resolveProjectDir(p)).filter(Boolean)
    : [];
  if (projectPaths.length < 2) return badRequest(res, 'a workspace needs at least 2 member projects');
  try {
    const { workspace, metricsHomeAuto } = await createWorkspaceWithHomes({
      name: body.name, projectPaths, description: body.description,
      metricsProject: body.metricsProject, policyProject: body.policyProject,
    });
    emitChanged('workspaces-changed', 'created');
    res.status(201).json({ workspace, metricsHomeAuto });
  } catch (err) {
    return workspaceFail(res, err);
  }
});

app.patch('/api/workspaces/:id', async (req, res) => {
  const id = req.params.id;
  if (!WORKSPACE_KEY_RE.test(id)) return res.status(404).json({ error: 'workspace not found' });
  const body = req.body || {};
  // The member set never changes via PATCH (defense-in-depth, §2.3): it has its own
  // route, POST /api/workspaces/:id/members, behind the live-run guard.
  if ('projectPaths' in body || 'projectKeys' in body) {
    return badRequest(res, 'PATCH accepts only name/description/metricsProject/policyProject; change members with POST /api/workspaces/:id/members');
  }
  // Pass through only the editable fields.
  const patch = {};
  if (typeof body.name === 'string') patch.name = body.name;
  if (typeof body.description === 'string') patch.description = body.description;
  if ('metricsProject' in body) {
    if (body.metricsProject !== null && typeof body.metricsProject !== 'string') {
      return badRequest(res, 'metricsProject must be a member project path or null');
    }
    patch.metricsProject = body.metricsProject;
  }
  if ('policyProject' in body) {
    if (body.policyProject !== null && typeof body.policyProject !== 'string') {
      return badRequest(res, 'policyProject must be a member project path or null');
    }
    patch.policyProject = body.policyProject;
  }
  try {
    const workspace = await updateWorkspace(id, patch);
    // A description edit may flip the origin to 'edited' (Regenerate appears); a rename re-renders a
    // generated description (its title line). Either way open Map tabs and editors re-read it.
    if ('description' in patch || 'name' in patch) emitChanged('workspaces-changed', 'map');
    if ('metricsProject' in patch) emitChanged('workspaces-changed', 'metrics-home');
    if ('policyProject' in patch) { emitChanged('workspaces-changed', 'policy-home'); emitChanged('team-policy-changed', 'policy-home'); }
    res.json({ workspace });
  } catch (err) {
    const status = workspaceErrorStatus(err && err.code);
    return res.status(status).json({ error: err && err.message ? err.message : String(err) });
  }
});

/** A run that owns this workspace blocks a member change: in THIS process any active run or a
 *  paused Workspace scan (ownsWorkspaceTarget) — except an automatic re-scan, which the change
 *  supersedes (supersedeRescans) — and any active run another live process (the CLI) owns: its
 *  metrics / policy home must not move under it. A crashed owner's row is reconciled first. */
function workspaceMembersBusy(id) {
  if ([...runs.values()].some((r) => r.workspaceId === id && !r.autoRescan && ownsWorkspaceTarget(r))) return true;
  const liveIds = [...runs.values()].flatMap((r) => [r.id, r.pipelineId]).filter(Boolean);
  try { reconcileStaleRunning({ liveIds: liveRunIds() }); } catch { /* best-effort */ }
  return foreignActiveWorkspaceRuns(id, { liveIds }).length > 0;
}

/** A resumed run gets a new entry (and runId): when the entry it resumes was an automatic
 *  re-scan, tag it again — the members route still supersedes it rather than refusing, and its
 *  end still reports to the workspace page — and tell the page to follow the new run. */
function markResumedRescan(entry) {
  const was = [...runs.values()].some((e) => e !== entry && e.pipelineId && e.pipelineId === entry.pipelineId && e.autoRescan && !e.superseded);
  if (!was) return;
  entry.autoRescan = true;
  broadcast({ type: 'workspaces-changed', action: 'rescan-resumed', workspaceId: entry.workspaceId, runId: entry.id });
}

/** Stop the automatic re-scan still owning a workspace: its member set is out of date.
 *  Awaited: a PAUSED re-scan settles only when its teardown ends, and until then it still
 *  owns the workspace — the new re-scan would be refused. */
async function supersedeRescans(id) {
  const stops = [];
  for (const r of runs.values()) {
    if (r.workspaceId !== id || !r.autoRescan || !ownsWorkspaceTarget(r)) continue;
    r.superseded = true;
    stops.push(stopRun(r.id, 'worca').catch(() => { /* best-effort: its save refuses a changed set anyway */ }));
  }
  await Promise.all(stops);
}

/**
 * Start a re-scan of a workspace from inside the server, through the same launch as
 * POST /api/workspaces/:id/scan (scanRequest), and tag its run as automatic. A workspace the
 * scan cannot read (a member that is not its own repository with a commit), a scan model that
 * no longer fits, or a signed-out CLI skips it with the reason — the page offers Re-scan.
 * { needsModel: true } when the workspace has no usable stored pick (the page asks the user).
 * @returns {Promise<{runId:string}|{skipped:string}|{needsModel:boolean}>}
 */
async function startAutoRescan(ws, { workflowId = WORKSPACE_SCAN_WORKFLOW_ID } = {}) {
  const problems = scanMemberProblems(ws.projectPaths);
  if (problems.length) return { skipped: `read-only workspace scan: ${problems.join('; ')}` };
  let models;
  try { models = await scanModelsFor({}, ws.projectPaths, ws); }
  catch (err) { return { skipped: err && err.message ? err.message : String(err) }; }
  // No usable stored pick (a legacy workspace, or one whose model left the catalog): the page
  // opens the pick-a-model window and starts the scan itself; the member change stands.
  if (models && models.needsModel) return { needsModel: true };
  if (!(models && modelHasBaseUrlRouting(models.scanModel))) {
    const { state } = await probeClaudeAuth({ bin: configuredClaudeBin(), mock: isTruthy(process.env.WORCA_MOCK ?? process.env.ORCH_MOCK) });
    if (state === 'signed-out') return { skipped: CLAUDE_SIGNED_OUT_MESSAGE };
  }
  let out = { status: 200, body: null };
  const res = {
    statusCode: 200, headersSent: false,
    status(code) { this.statusCode = code; return this; },
    json(payload) { out = { status: this.statusCode, body: payload }; this.headersSent = true; return this; },
  };
  await scanRequest({ body: {} }, res, { id: ws.id, name: ws.name, projectPaths: ws.projectPaths, rescan: true, models, workflowId });
  const runId = out.body && out.body.runId;
  const entry = runId ? runs.get(runId) : null;
  if (!entry) return { skipped: (out.body && out.body.error) || `the re-scan could not start (HTTP ${out.status})` };
  entry.autoRescan = true;
  return { runId };
}

let autoRescanOn = true; // test seam: _testing.setAutoRescan(false) skips the re-scan a member change starts

/** The re-scan worca recommends for removing `projectPath` (src/core/workspaces.mjs
 *  memberRemoveImpact over the map as stored now). A live automatic re-scan this change would
 *  replace (supersedeRescans) raises it: the earlier change still needs its re-scan. A just-resumed
 *  partial run still reads 'wf_default' until _resume() restores its workflowId, so for that moment
 *  it counts as 'full' — the safe direction (it recommends more, never less). Throws
 *  removeWorkspaceMember's own coded refusals. `git`: a memoGitProbe shared with the removal. */
function removeRecommendation(id, projectPath, git) {
  const auto = liveAutoRescan(id);
  const pendingRescan = !auto ? null : auto.orch?.workflowId === WORKSPACE_RESYNTH_WORKFLOW_ID ? 'partial' : 'full';
  return removeImpactFor(id, projectPath, { pendingRescan, ...(git ? { git } : {}) });
}

/** A removal re-scanned with 'none' against a 'full' recommendation can leave the map short: a
 *  member it never covered, or an earlier change's re-scan this one stopped (supersedeRescans).
 *  The pruned notice says so (rescan.note) — the pick stands. */
function prunedNote(rec) {
  const s = (rec && rec.signals) || {};
  if (s.uncovered && s.uncovered.length) return `The map still does not cover ${s.uncovered.join(', ')}.`;
  if (s.pendingRescan) return 'The re-scan for an earlier member change was stopped, so the map may be missing what it changed.';
  return null;
}

/**
 * After a member change (the members route and Ask's workspace card): discover the added
 * members' metrics / policy branches (so the Team tab and the homes read them at once), stop an
 * automatic re-scan of the old set, and re-scan as asked — 'full' (every member: graphs, map, description), 'partial' (wf_workspace_resynth: the
 * synthesis rewritten from the stored, pruned map) or 'none' (the pruned map stands). Adds are
 * always 'full'. A 'partial' whose stored map does not cover exactly the members (resynthBlocker)
 * runs 'full' instead, with a `note` saying why — decided HERE, before launch, so a partial run that
 * cannot work never starts (its seed would pause it, and a paused one owns the workspace).
 * Runs build their own graphs per member worktree from the registry at start.
 * @returns {Promise<{mode:'none'|'partial'|'full', runId?:string, skipped?:string, needsModel?:boolean, note?:string}>}
 */
async function afterMembersChanged(workspace, added = [], { rescan = 'full' } = {}) {
  for (const dir of added) {
    if (getProjectByPath(dir)?.vcs === 'none') continue;   // P5: a Folder member has no origin of its own (nested in a repository it would take that one's)
    discoverProject(dir, { force: true }).then(() => emitChanged('team-metrics-changed', 'discovered')).catch(() => { /* retried hourly */ });
    discoverPolicy(dir, { force: true }).then(() => emitChanged('team-policy-changed', 'discovered')).catch(() => { /* retried hourly */ });
  }
  await supersedeRescans(workspace.id);
  if (rescan === 'none') return { mode: 'none' };
  let mode = rescan === 'partial' ? 'partial' : 'full';
  let note = null;
  if (mode === 'partial') {
    const stored = await readWorkspaceMap(workspace.id);
    const why = resynthBlocker(stored && stored.map, workspace.projectKeys || []);
    if (why) { mode = 'full'; note = `A partial re-scan could not run: ${why}. A full re-scan runs instead.`; }
  }
  const told = note ? { note } : {};
  if (!autoRescanOn) return { mode, ...told, skipped: 'automatic re-scans are off (test seam)' };
  const workflowId = mode === 'partial' ? WORKSPACE_RESYNTH_WORKFLOW_ID : WORKSPACE_SCAN_WORKFLOW_ID;
  try { return { mode, ...told, ...(await startAutoRescan(workspace, { workflowId })) }; }
  catch (err) { return { mode, ...told, skipped: err && err.message ? err.message : String(err) }; }
}

// What removing one member would invalidate in the stored map, and the re-scan worca recommends
// (none | partial | full) with its reason — read-only, computed in code (no model call) BEFORE
// anything changes, so the Remove confirm can show it. The removal's own refusals: 400 not a
// member / fewer than two left, 404 unknown workspace.
app.get('/api/workspaces/:id/members/remove-impact', async (req, res) => {
  const id = req.params.id;
  if (!WORKSPACE_KEY_RE.test(id)) return res.status(404).json({ error: 'workspace not found' });
  const projectPath = typeof req.query.path === 'string' ? req.query.path : '';
  if (!projectPath) return badRequest(res, 'give path (the member project to remove)');
  try {
    res.json({ recommendation: removeRecommendation(id, projectPath) });
  } catch (err) {
    return workspaceFail(res, err);
  }
});

// Change the member set: body {add: [paths]} or {remove: path, rescan?: 'none'|'partial'|'full'}.
// The id stays frozen (workspaces.mjs D1). 409 while a run (or a scan the user started) owns the
// workspace — a live run keeps its own frozen members, but the metrics / policy home it resolves at
// its end must not move under it, and a scan would save a map of the old set. Removing the home
// member clears that home (clearedHomes). An add always re-scans in full. A removal re-scans as
// asked; with no `rescan` the server applies its own recommendation (removeRecommendation), worked
// out from the stored map BEFORE it is pruned and returned as `recommendation`. A partial the
// recommendation marks unavailable (no stored map, or one that does not cover the members left) is a 400.
app.post('/api/workspaces/:id/members', async (req, res) => {
  const id = req.params.id;
  if (!WORKSPACE_KEY_RE.test(id)) return res.status(404).json({ error: 'workspace not found' });
  const body = req.body || {};
  const adding = Array.isArray(body.add);
  const removing = typeof body.remove === 'string';
  if (adding === removing) return badRequest(res, 'give add (an array of project paths) or remove (one project path)');
  const asked = body.rescan === undefined || body.rescan === null ? null : body.rescan;
  if (asked !== null && !RESCAN_CHOICES.includes(asked)) return badRequest(res, `rescan must be one of ${RESCAN_CHOICES.join(', ')}`);
  if (adding && asked !== null && asked !== 'full') return badRequest(res, 'adding members always starts a full re-scan');
  if (workspaceMembersBusy(id)) return res.status(409).json({ error: 'cannot change the members of a workspace while a run or scan owns it' });
  try {
    const before = await readWorkspace(id);
    if (!before) return res.status(404).json({ error: 'workspace not found' });
    const git = memoGitProbe();   // one set of git probes for the recommendation and the removal
    const recommendation = removing ? removeRecommendation(id, body.remove, git) : null;
    const mode = adding ? 'full' : (asked ?? recommendation.level);
    if (mode === 'partial' && !recommendation.partialAvailable) {
      return badRequest(res, `a partial re-scan is not available: ${recommendation.reason} Choose none or full.`);
    }
    const workspace = adding
      ? await addWorkspaceMembers(id, body.add.map((p) => resolveProjectDir(p)).filter(Boolean))
      : await removeWorkspaceMember(id, body.remove, { git });
    let rescan = await afterMembersChanged(workspace, workspace.projectPaths.filter((p) => !before.projectPaths.includes(p)), { rescan: mode });
    const short = rescan.mode === 'none' ? prunedNote(recommendation) : null;
    if (short) rescan = { ...rescan, note: short };
    const clearedHomes = [
      ...(before.metricsProject && !workspace.metricsProject ? ['metrics'] : []),
      ...(before.policyProject && !workspace.policyProject ? ['policy'] : []),
    ];
    emitChanged('workspaces-changed', 'members');
    if (clearedHomes.includes('policy')) emitChanged('team-policy-changed', 'policy-home');
    res.json({ workspace, clearedHomes, rescan, ...(recommendation ? { recommendation } : {}) });
  } catch (err) {
    return workspaceFail(res, err);
  }
});

app.delete('/api/workspaces/:id', async (req, res) => {
  const id = req.params.id;
  if (!WORKSPACE_KEY_RE.test(id)) return res.status(404).json({ error: 'workspace not found' });
  // 409 while a live workspace run exists — a paused Workspace scan included: it would re-create
  // the workspace when resumed (ownsWorkspaceTarget). The module-level deleteWorkspace has no runs
  // map, so this guard lives here (§2.3).
  const live = [...runs.values()].some((r) => r.workspaceId === id && ownsWorkspaceTarget(r));
  if (live) return res.status(409).json({ error: 'cannot delete a workspace with a live run' });
  try {
    const report = await deleteWorkspace(id);
    try { if (cancelForTarget({ workspaceId: id })) emitChanged('schedules-changed', 'target-removed'); }
    catch (err) { console.error(`[worca-ui] schedule cleanup failed: ${err && err.message ? err.message : err}`); }
    emitChanged('workspaces-changed', 'deleted');
    res.json({ ok: true, warnings: (report && report.warnings) || [] });
  } catch (err) {
    const status = workspaceErrorStatus(err && err.code);
    return res.status(status).json({ error: err && err.message ? err.message : String(err) });
  }
});

// ---------------------------------------------------------------------------
// Workspace map: the last scan's structured result and its review. Validation and the
// read-modify-write of the overrides live in workspaces.mjs (one transaction each, so two
// quick clicks never lose one another); every change broadcasts workspaces-changed{map}.
//   GET    /api/workspaces/:id/map                 { map, synthesis, overrides, edges, descriptionOrigin }
//   PUT    /api/workspaces/:id/map/edges/:edgeId   { state: 'confirmed'|'rejected'|null } (scanned x_ edges)
//   POST   /api/workspaces/:id/map/edges           { from, to, kind, display, detail? } -> 201 (200 when it exists)
//   DELETE /api/workspaces/:id/map/edges/:edgeId   manual m_ edges only (x_ -> 400)
//   POST   /api/workspaces/:id/map/render          "Regenerate description"
// ---------------------------------------------------------------------------
app.get('/api/workspaces/:id/map', async (req, res) => {
  const id = req.params.id;
  if (!WORKSPACE_KEY_RE.test(id)) return res.status(404).json({ error: 'workspace not found' });
  try {
    const data = await readWorkspaceMap(id);
    if (!data) return res.status(404).json({ error: 'workspace not found' });
    res.json({ ...data, edges: effectiveEdges(data.map, data.overrides) });
  } catch (err) {
    return workspaceFail(res, err);
  }
});

app.put('/api/workspaces/:id/map/edges/:edgeId', async (req, res) => {
  const id = req.params.id;
  if (!WORKSPACE_KEY_RE.test(id)) return res.status(404).json({ error: 'workspace not found' });
  const body = req.body || {};
  if (!Object.prototype.hasOwnProperty.call(body, 'state')) return badRequest(res, 'state must be "confirmed", "rejected" or null');
  try {
    const out = await setWorkspaceEdgeState(id, req.params.edgeId, body.state);
    emitChanged('workspaces-changed', 'map');
    res.json({ edge: out.edge, overrides: out.overrides, rerendered: out.rerendered, workspace: out.workspace });
  } catch (err) {
    return workspaceFail(res, err);
  }
});

app.post('/api/workspaces/:id/map/edges', async (req, res) => {
  const id = req.params.id;
  if (!WORKSPACE_KEY_RE.test(id)) return res.status(404).json({ error: 'workspace not found' });
  const body = req.body || {};
  try {
    const out = await addWorkspaceManualEdge(id, {
      from: body.from, to: body.to, kind: body.kind, display: body.display, detail: body.detail,
    });
    if (out.created) emitChanged('workspaces-changed', 'map');
    res.status(out.created ? 201 : 200)
      .json({ edge: out.edge, overrides: out.overrides, rerendered: out.rerendered, workspace: out.workspace });
  } catch (err) {
    return workspaceFail(res, err);
  }
});

app.delete('/api/workspaces/:id/map/edges/:edgeId', async (req, res) => {
  const id = req.params.id;
  if (!WORKSPACE_KEY_RE.test(id)) return res.status(404).json({ error: 'workspace not found' });
  try {
    const out = await removeWorkspaceManualEdge(id, req.params.edgeId);
    emitChanged('workspaces-changed', 'map');
    res.json({ ok: true, overrides: out.overrides, rerendered: out.rerendered, workspace: out.workspace });
  } catch (err) {
    return workspaceFail(res, err);
  }
});

app.post('/api/workspaces/:id/map/render', async (req, res) => {
  const id = req.params.id;
  if (!WORKSPACE_KEY_RE.test(id)) return res.status(404).json({ error: 'workspace not found' });
  try {
    const workspace = await regenerateWorkspaceDescription(id);
    emitChanged('workspaces-changed', 'map');
    res.json({ workspace });
  } catch (err) {
    return workspaceFail(res, err);
  }
});

// ---------------------------------------------------------------------------
// Workspace scan (wf_workspace_scan): a regular pipeline run over a workspace target that may
// not exist yet. The routes validate, then hand startRunHandler an in-process target; the run
// harness creates/updates the workspace when the run ends done (workspace-scan-run.mjs).
// ---------------------------------------------------------------------------

/** Roots hashes of scans between their 409 check and their runs entry: startRunHandler awaits
 *  several things (workflow + guardrail lookups, the team gate, the orchestrator build) before
 *  `runs.set`, so a second tab's POST in that window would otherwise pass the check too
 *  (Review Focus 3). Taken synchronously right after the check, dropped once startRunHandler
 *  has answered — by then the runs entry exists. */
const pendingScans = new Set();

/** The 8-hex roots hash of the set a run's workspace spans: the stored workspace's CURRENT members
 *  (its id keeps the hash of the set it was created over — members can change since), else the
 *  hash its id ends in (workspaces.mjs workspaceKey; a first scan's workspace does not exist yet). */
const setHashOf = (id) => workspaceSetHash(id) ?? String(id).slice(-8);

/** A run entry that still owns its workspace target: any ACTIVE run (no workflowId test — a
 *  just-resumed entry reads `wf_default` until resume() restores it), or a PAUSED Workspace scan
 *  (it resumes into the target and saves it when done; its entry kept the workflowId it was built
 *  with). A paused ordinary run holds the target no more than it did before scans were runs: it
 *  blocks neither a re-scan nor a delete. The DELETE guard (Step 8) uses it too. */
function ownsWorkspaceTarget(r) {
  const s = String(r.status || '').toLowerCase();
  return ['created', 'starting', 'running', 'pausing'].includes(s)
    || (s === 'paused' && isWorkspaceScanWorkflow(r.orch?.workflowId));
}

/** A run of this workspace or over this PROJECT SET that owns it, or a scan of the set still
 *  launching. For a first scan the set has no workspace (checkNewWorkspace refused a duplicate set),
 *  so any such run IS a scan, under any name; for a re-scan it is any active run of that workspace
 *  or a paused scan of it (D4). */
function liveOverSet(id, projectPaths) {
  const hash = rootsHash(projectPaths);
  if (pendingScans.has(hash)) return true;
  return [...runs.values()].some((r) => r.kind === 'workspace-run' && typeof r.workspaceId === 'string'
    && ownsWorkspaceTarget(r) && (r.workspaceId === id || setHashOf(r.workspaceId) === hash));
}

/** The run's primary member: the lowest projectKey — startRunHandler sorts members the same way,
 *  and the run resolves its models against THIS member's catalog. checkNewWorkspace returns the
 *  paths in request order, so never take [0]. */
function primaryMemberOf(paths) {
  return [...paths].sort((x, y) => { const a = projectKey(x), b = projectKey(y); return a < b ? -1 : a > b ? 1 : 0; })[0];
}

/**
 * Refuse a detached Claude job (workspace scan, agent generation) up front when
 * the CLI is signed out (preflight probeClaudeAuth): otherwise it starts and its
 * first agent dies ~30 s in with "Not logged in". Only a definite 'signed-out'
 * refuses — mock, an auth env var, or an unknown answer (an older CLI) all pass.
 * Sends the 409 and returns true when it refused.
 */
async function refuseSignedOutClaude(res) {
  const { state } = await probeClaudeAuth({ bin: configuredClaudeBin(), mock: serverMockMode() });
  if (state !== 'signed-out') return false;
  res.status(409).json({ code: CLAUDE_SIGNED_OUT_CODE, error: CLAUDE_SIGNED_OUT_MESSAGE });
  return true;
}

/**
 * The gate for a workspace scan: only a first-party scan agent needs the CLI signed in. On an
 * endpoint-routed scan model (the stamp the orchestrator puts on the node, endpointRouted) the
 * investigators stay on that endpoint too (phases.mjs sameEndpointSubagentDirective), so a
 * signed-out install that reaches its models through a gateway (auto/runnable.mjs) still scans.
 */
async function refuseSignedOutScan(res, models) {
  if (models && modelHasBaseUrlRouting(models.scanModel)) return false;
  return refuseSignedOutClaude(res);
}

/** Whether the workspace's OWN stored scan pick still holds against the primary member's catalog.
 *  Missing/empty catalog = "no info" (e.g. a failed catalog GET) condemns nothing, matching
 *  resolveScanModels' defaultScanModelsOrThrow. A pick whose scan model left the catalog (or no
 *  longer offers its effort) is UNUSABLE: it would fail at the endpoint, so the rescan must ask the
 *  user instead of silently degrading to Settings/default (the pick was deliberately chosen once). */
function workspacePickUsable(pick, models) {
  if (!pick || typeof pick !== 'object') return false;
  if (!Array.isArray(models) || !models.length) return true;
  try { assertWorkspaceScanInput(pick, models); return true; } catch { return false; }
}

/** The scan's models (D18, D19): the request's pick, else the workspace's stored pick (source
 *  'workspace' — captured at creation, reused by auto re-scans), else Settings › Runs › Workspaces,
 *  else the defaults (only when a known catalog offers the default) — checked against the primary
 *  member's catalog. Throws on a bad explicit pick (400) or when no model is available (D19).
 *  A RE-SCAN of a workspace with no usable stored pick — every legacy pre-v57 workspace, or one
 *  whose model left the catalog — is NOT silently resolved: scanModelsFor returns the marker
 *  { needsModel: true, models: <PRIMARY_CATALOG> } and the caller asks the user to pick a model
 *  (D20). An explicit body.models always wins (the prompted client sends one; API/CLI callers can
 *  still force a pick). */
async function scanModelsFor(body, projectPaths, workspace = null) {
  const models = await listModels(primaryMemberOf(projectPaths));
  if (workspace && !(body && body.models) && !workspacePickUsable(workspace.scanModels, models)) {
    return { needsModel: true, models };
  }
  return resolveScanModels({
    explicit: body && body.models,
    // Model roles (D3): with no stored pick, the quick role is the scan model.
    stored: withScanRole(workspaceScanModels(), WORKSPACE_SCAN_DEFAULT_MODELS),
    workspacePick: workspace && workspace.scanModels ? workspace.scanModels : null,
    models,
  });
}

/** Start a scan through the ONE run handler (the defragRequest pattern). startRunHandler reads
 *  req.body once at its top, so rewriting it here is sound. The body names no source/feature
 *  branch: every member runs from its default branch on a run-owned `worca-cc/…` branch, which
 *  teardown deletes (D5). The live check and the reservation are the first two statements, with
 *  NO await between them: a second request for the same set, arriving while this one is still
 *  inside startRunHandler's awaits, finds the reservation and gets 409 (Review Focus 3). */
async function scanRequest(req, res, { id, name, projectPaths, rescan, models, workflowId = WORKSPACE_SCAN_WORKFLOW_ID }) {
  if (liveOverSet(id, projectPaths)) {
    return res.status(409).json({ error: rescan ? 'a live run exists for this workspace' : 'a scan of this project set is already running' });
  }
  const hash = rootsHash(projectPaths);
  pendingScans.add(hash);
  try {
    const mock = !!(req.body && req.body.mock === true);
    req._workspaceScan = { id, name, projectPaths, description: '', models };   // D9: no Workspace Context
    const partial = workflowId === WORKSPACE_RESYNTH_WORKFLOW_ID;
    req.body = {
      workspaceId: id,
      prompt: scanRunPrompt({ name, projectNames: projectPaths.map((p) => path.basename(p)), rescan, partial }),
      title: scanRunTitle(name, { partial }),
      workflowId,
      guardrailsId: 'normal',
      ...(mock ? { mock: true } : {}),
    };
    return await startRunHandler(req, res);
  } finally {
    pendingScans.delete(hash);
  }
}

// POST /api/workspaces/import-candidates {paths?: string[], text?: string, depth?: 1|2}
//   -> 200 {candidates, workspaceName, truncated}
// The creation wizard's Add… and paste box: what each path is (a repository, a folder of
// repositories, a VS Code .code-workspace file) as review rows — registered (the existing project),
// new (the wizard registers it through POST /api/projects/bulk before it scans) or problem (with
// the reason). Reads folders and runs `git rev-parse` only: it never writes (src/core/workspace-
// import.mjs). On a hosted Worca it reads only inside Worca's own folders (fs-scope.mjs).
app.post('/api/workspaces/import-candidates', async (req, res) => {
  const body = req.body && typeof req.body === 'object' ? req.body : {};
  if (body.paths !== undefined && !Array.isArray(body.paths)) return badRequest(res, 'paths must be an array of paths');
  if (body.text !== undefined && typeof body.text !== 'string') return badRequest(res, 'text must be a string');
  try {
    // Picked and pasted paths, duplicates removed BEFORE the count: the same 60 paths picked and
    // pasted are 60 inputs. parsePathList stops just past the limit, so a huge paste stays cheap.
    const inputs = [...new Set([
      ...(body.paths || []).filter((p) => typeof p === 'string' && p.trim()).map((p) => p.trim()),
      ...parsePathList(body.text || '', IMPORT_MAX_INPUTS),
    ])];
    if (!inputs.length) return badRequest(res, 'give at least one path (paths or text)');
    if (inputs.length > IMPORT_MAX_INPUTS) return badRequest(res, `at most ${IMPORT_MAX_INPUTS} paths per import`);
    // On a hosted Worca the import reads only inside Worca's own folders, like the folder browser.
    const roots = fsLimitedHere(req) ? await fsAllowedRoots() : null;
    const outsideProblem = roots ? async (p) => ((await checkInside(p, roots)).inside ? null : outsideAllowedMessage(p)) : null;
    res.json(await importCandidates(inputs, { depth: body.depth === 2 ? 2 : 1, projects: await listProjects(), outsideProblem }));
  } catch (err) {
    if (!res.headersSent) res.status(500).json({ error: err && err.message ? err.message : String(err) });
  }
});

// POST /api/workspaces/scan (first scan): validated exactly as the save will be (D4).
app.post('/api/workspaces/scan', async (req, res) => {
  const body = req.body || {};
  const projectPaths = Array.isArray(body.projectPaths)
    ? body.projectPaths.map((p) => resolveProjectDir(p)).filter(Boolean)
    : [];
  if (projectPaths.length < 2) return badRequest(res, 'a workspace scan needs at least 2 member projects');
  let target;
  try {
    target = checkNewWorkspace({ name: body.name, projectPaths });
  } catch (err) {
    return res.status(workspaceErrorStatus(err && err.code)).json({ error: err && err.message ? err.message : String(err) });
  }
  // A scan never inits or commits a member (scan D5): every member must be its own repository with a commit.
  const problems = scanMemberProblems(target.projectPaths);
  if (problems.length) return badRequest(res, `read-only workspace scan: ${problems.join('; ')}`);
  let models;
  try { models = await scanModelsFor(body, target.projectPaths); }
  catch (err) { return badRequest(res, err && err.message ? err.message : String(err)); }
  if (await refuseSignedOutScan(res, models)) return;
  return scanRequest(req, res, { ...target, rescan: false, models });
});

// POST /api/workspaces/:id/scan (re-scan): the description is replaced when the run ends done.
// 428 SCAN_MODEL_REQUIRED when the workspace has no usable stored scan pick and the request names
// none — the page opens the pick-a-model window (a legacy pre-v57 workspace, or a pick whose model
// left the catalog, must never silently fall to Settings/default). An explicit body.models always
// proceeds; the prompted page sends it after the user picks. `autoRescan: true` (internal) tags the
// run so the next member change supersedes it exactly like a server-started auto-rescan.
app.post('/api/workspaces/:id/scan', async (req, res) => {
  const id = req.params.id;
  if (!WORKSPACE_KEY_RE.test(id)) return res.status(404).json({ error: 'workspace not found' });
  try {
    const ws = await readWorkspace(id);
    if (!ws) return res.status(404).json({ error: 'workspace not found' });
    // ws.id is the stored id (a renamed workspace keeps its id; never recompute workspaceKey here).
    // Plain create accepts any git work tree; a scan also needs each member to be its own repository with a commit.
    const problems = scanMemberProblems(ws.projectPaths);
    if (problems.length) return badRequest(res, `read-only workspace scan: ${problems.join('; ')}`);
    let models;
    try { models = await scanModelsFor(req.body || {}, ws.projectPaths, ws); }
    catch (err) { return badRequest(res, err && err.message ? err.message : String(err)); }
    if (await refuseSignedOutScan(res, models)) return;
    if (models && models.needsModel) {
      return res.status(428).json({
        code: 'SCAN_MODEL_REQUIRED', workspace: ws,
        error: 'This workspace has no scan model saved (or the saved model is no longer available) — choose one to scan.',
      });
    }
    if (req.body && req.body.autoRescan === true) {
      // The prompted add/remove flow: start it like startAutoRescan would (same stub-res capture,
      // same autoRescan tag) so a next member change supersedes this run exactly like a
      // server-started auto-rescan.
      let out = { status: 200, body: null };
      const stub = {
        statusCode: 200, headersSent: false,
        status(c) { this.statusCode = c; return this; },
        json(p) { out = { status: this.statusCode, body: p }; this.headersSent = true; return this; },
      };
      await scanRequest(req, stub, { id: ws.id, name: ws.name, projectPaths: ws.projectPaths, rescan: true, models });
      const runId = out.body && out.body.runId;
      const entry = runId ? runs.get(runId) : null;
      if (entry) entry.autoRescan = true;
      return res.status(out.status).json(out.body || {});
    }
    return await scanRequest(req, res, { id: ws.id, name: ws.name, projectPaths: ws.projectPaths, rescan: true, models });
  } catch (err) {
    if (!res.headersSent) res.status(500).json({ error: err && err.message ? err.message : String(err) });
  }
});

// PUT /api/workspaces/:id/scan-models — the workspace's OWN scan-model pick (the page's "Scan
// model" header control and the pick-a-model window a rescan opens). Body { workspaceScan:
// { scanModel, scanEffort, agentModel, agentEffort } } or null to clear. Validated against the
// primary member's catalog (mirrors the Settings route); persisted via setWorkspaceScanPick, which
// re-reads under the write lock so a pick a scan's finalize landed mid-write is never clobbered.
app.put('/api/workspaces/:id/scan-models', async (req, res) => {
  const id = req.params.id;
  if (!WORKSPACE_KEY_RE.test(id)) return res.status(404).json({ error: 'workspace not found' });
  try {
    const ws = await readWorkspace(id);
    if (!ws) return res.status(404).json({ error: 'workspace not found' });
    const hasKey = req.body && Object.prototype.hasOwnProperty.call(req.body, 'workspaceScan');
    const raw = hasKey ? req.body.workspaceScan : undefined;
    if (!hasKey) return badRequest(res, 'give workspaceScan: { scanModel, scanEffort, agentModel, agentEffort } or null to clear');
    let pick;
    try { pick = assertWorkspaceScanInput(raw, await listModels(primaryMemberOf(ws.projectPaths))); }
    catch (err) { return badRequest(res, err && err.message ? err.message : String(err)); }
    const workspace = await setWorkspaceScanPick(id, pick);
    emitChanged('workspaces-changed', 'scan-models');
    res.json({ workspace });
  } catch (err) {
    if (!res.headersSent) return res.status(workspaceErrorStatus(err && err.code)).json({ error: err && err.message ? err.message : String(err) });
  }
});

// ---------------------------------------------------------------------------
// GET /api/workspaces/:id/runs/:runId  -> persisted state + markdown for a
// finished workspace run. The /api/history/:key/:id key regex forbids a slash,
// so a workspace run (store key "workspaces/<key>") needs this dedicated route.
// readWorkspacePipeline joins ONLY workspaceStorePath(validatedKey) -> no
// path-traversal surface; do NOT widen the history :key regex (§2.7).
// ---------------------------------------------------------------------------
app.get('/api/workspaces/:id/runs/:runId', async (req, res) => {
  const id = req.params.id;
  if (!WORKSPACE_KEY_RE.test(id)) return res.status(404).json({ error: 'pipeline not found' });
  try {
    const data = await readWorkspacePipeline(id, req.params.runId);
    if (!data) return res.status(404).json({ error: 'pipeline not found' });
    res.json(data);
  } catch (err) {
    res.status(500).json({ error: err && err.message ? err.message : String(err) });
  }
});

app.get('/api/workspaces/:id/runs/:runId/log', async (req, res) => {
  if (!WORKSPACE_KEY_RE.test(req.params.id)) {
    return res.status(404).json({ error: 'pipeline not found' });
  }
  try {
    const text = await readRunLogText(`workspaces/${req.params.id}`, req.params.runId);
    if (text == null) return res.status(404).json({ error: 'no log' });
    res.type('application/x-ndjson').send(text);
  } catch (err) {
    res.status(500).json({ error: err && err.message ? err.message : String(err) });
  }
});

// NOTE: the /comments twins for workspace runs are registered with their project
// siblings up at the diff-comments block — the pair must be read together.
app.get('/api/workspaces/:id/runs/:runId/diff', async (req, res) => {
  if (!WORKSPACE_KEY_RE.test(req.params.id)) {
    return res.status(404).json({ error: 'pipeline not found' });
  }
  try {
    const text = await readRunArtifactText(`workspaces/${req.params.id}`, req.params.runId, DIFF_PATCH_FILE);
    if (text == null) return res.status(404).json({ error: 'no diff' });
    res.type('text/x-diff').send(text);
  } catch (err) {
    res.status(500).json({ error: err && err.message ? err.message : String(err) });
  }
});

// The End-card result chip's workspace twin (see the project route above).
app.get('/api/workspaces/:id/runs/:runId/artifact', async (req, res) => {
  if (!WORKSPACE_KEY_RE.test(req.params.id)) return res.status(404).json({ error: 'pipeline not found' });
  try {
    const hit = await resolveIndexedArtifact(`workspaces/${req.params.id}`, req.params.runId, req.query.rel);
    if (!hit) return res.status(404).json({ error: 'artifact not found' });
    res.json(hit);
  } catch (err) {
    res.status(500).json({ error: err && err.message ? err.message : String(err) });
  }
});

// The ask-form preview twin for a workspace run (see the project route above).
// WORKSPACE_KEY_RE is the only validation the id needs; the key is composed here
// and never taken from the client, so there is no path-traversal surface.
app.get('/api/workspaces/:wid/runs/:id/ask-files/:askId/:index', async (req, res) => {
  if (!WORKSPACE_KEY_RE.test(req.params.wid)) return res.status(404).json({ error: 'pipeline not found' });
  try {
    await serveAskFile(res, await askFilesStoreDir(`workspaces/${req.params.wid}`, req.params.id),
      req.params.askId, req.params.index);
  } catch (err) {
    res.status(500).json({ error: err && err.message ? err.message : String(err) });
  }
});

app.get('/api/workspaces/:id/runs/:runId/artifact-raw/*', async (req, res) => {
  if (!WORKSPACE_KEY_RE.test(req.params.id)) return res.status(404).json({ error: 'pipeline not found' });
  try {
    const row = lookupPipelineRow(`workspaces/${req.params.id}`, req.params.runId);
    if (!row) return res.status(404).json({ error: 'artifact not found' });
    await sendArtifactRaw(res, row, req.params[0], { download: req.query.download === '1' });
  } catch (err) { res.status(500).json({ error: err && err.message ? err.message : String(err) }); }
});

// ---------------------------------------------------------------------------
// GET /api/settings  -> { root, projectsRoot, projectsRootDefault, default }
//   root                : the configured Worca CC data-root base, '' when unset
//                         (the `default` field is what applies then).
//   projectsRoot        : the RAW persisted projectsRoot (§5.1), '' when unset —
//                         the same raw contract as `root`, NOT the effective
//                         value. Two reasons this is not getProjectsRoot():
//                         (a) an effective value is never '', so "unset" would be
//                         indistinguishable from "explicitly set" and the UI's
//                         "leave blank" affordance would be unreachable;
//                         (b) WORCA_PROJECTS_ROOT would be echoed as if stored,
//                         and the next Save would promote that env override into
//                         settings.json. Runs still resolve via getProjectsRoot().
//   projectsRootDefault : what applies when projectsRoot is blank — the env tier
//                         when exported, else <worcaHome>/projects. The UI placeholder.
//                         Additive; `default` keeps its `root` meaning.
//   app                 : { version, repoUrl, releaseUrl } — static identity for
//                         the About card (APP_INFO, from package.json). GET-only:
//                         it is not a setting, so POST keeps echoing
//                         settingsState() + chat unchanged.
// POST /api/settings -> set either key and return the resulting full state.
//   Only keys PRESENT in the body are written, so a projectsRoot-only POST can
//   never reset `root` (and vice versa). An explicitly empty value still resets
//   that one key. A body with neither key keeps today's contract: it resets root.
//   The other settings keys (runRootMode, the two context caps, skillMount) are
//   settings-file-only in this change and deliberately not exposed here.
// Validation lives in src/core/settings.mjs; this is thin delegation mirroring
// /api/projects.
// ---------------------------------------------------------------------------
const settingsState = () => ({
  root: getWorcaRoot(), projectsRoot: rawProjectsRoot(),
  projectsRootDefault: defaultProjectsRoot(), default: defaultRoot(),
  pipelineCostLimitUsd: pipelineCostLimitUsd(),
  totalCostLimitUsd: totalCostLimitUsd(),
  costLimitResetPeriod: costLimitResetPeriod(),
  humanRateUsdPerHour: humanRateUsdPerHour(),
  askMaxTurns: askMaxTurns(),
  askMaxBudgetUsd: askMaxBudgetUsd(),
  askWeb: askWeb(),                                       // Chat web access (off by default)
  smartNaming: smartNaming(),                             // Smart run naming (flag smartRunNaming)
  debugSpawnEnabled: storedDebugSpawnEnabled(),          // what is STORED (the checkbox)
  debugSpawnEffective: effectiveDebugSpawn(),             // what the next spawn will DO, and why
  resumeAfterUsageLimit: resumeAfterUsageLimit(),
  autoGeneratePrDescription: autoGeneratePrDescription(), // Create PR: Generate with AI on open
  updateCheck: updateCheckEnabled(),                    // Settings › About: npm latest check (#841)
  titleModel: storedTitleModel(),                         // the STORED id (the select), null = run's model
  titleModelEffective: describeTitleModel(),              // env override / stale id, for the hint line (#422)
  hideBuiltinModels: hideBuiltinModels(),
  theme: storedTheme(),                                   // system | light | dark (dark-mode design §6)
  schedule: scheduleDefaults(),                           // defaults a NEW schedule inherits
  tagDimensions: userTagDimensions(),                     // Settings › Tags › Tag dimensions (local; a team policy's list wins)
  enforceTags: userEnforceTags(),                         // Settings › Tags (local; a team policy's runs.enforceTags wins)
  sync: syncDefaults(),                                   // sync before run (#527): instance defaults
  networkWait: networkWaitSettings(),                     // Settings › Runs › Wait for the network
  uiLevel: effectiveUiLevel(),                            // simple | advanced | expert (docs/ui-levels.md)
  flags: allFlags(),                                      // { key: bool } resolved (docs/feature-flags.md)
  git: (({ available, version }) => ({ available, version }))(currentGitState()),   // is git usable here (CONTRACT §0)
  memoryDefrag: memoryDefragModel(),                      // Settings › Memory: the STORED { model, effort } (null = the workflow default)
  memoryDefragDefault: defragDefaultModel(),              // what "(default)" means there: the built-in's own model
  workspaceScan: workspaceScanModels(),                   // Settings › Runs › Workspaces: the STORED pick (null = the defaults)
  workspaceScanDefault: WORKSPACE_SCAN_DEFAULT_MODELS,    // what null means: Sonnet 5 · medium, project agents sonnet · medium
  runEngine: runEngineSetting() ?? null,
  // Raw values (unlike askMaxTurns): an unset field stays empty and Save never persists a default nobody typed.
  execEnv: execEnvSetting() ?? null,
  e2bMaxSandboxes: e2bIntSettingRaw('e2bMaxSandboxes'),
  e2bMaxWaitMin: e2bIntSettingRaw('e2bMaxWaitMin'),
  stepModels: stepModelsSetting(),
  modelRoles: modelRolesSetting(),                         // Models › Roles (D1): { <engine>: { deep|everyday|quick: { model, effort } } }
  utilityModels: utilityModelsSetting(),
  askEngine: askEngineSetting() ?? null,                  // Chat: the engine new chats start on (D17)
  // Models › Engines › Claude: the STORED { model?, effort? } (null = the default); only while the requirements flag is on
  ...(flagEnabled('requirements') ? { requirementsInterview: requirementsInterviewSetting() ?? null } : {}),
  askModels: askModelsSetting(),                          // Chat: the model per engine (D17)
  nightMode: nightModeSettings(),                         // night mode: the user layer (only the fields set)
  nightModeEffective: resolveNightConfig({ user: nightModeSettings() }).config,   // no project: the global view
  nightModeToggle: nightModeToggle(),                     // auto | on | off (live switch)
  keepAwake: keepAwakeEnabled(),                          // the account menu's Keep awake switch
  actions: actionsSettings(),                             // Settings › Runs › Actions (issue #529)
  actionsDetected: autoDetectedBuiltins(),                // what Editor / Terminal fall back to when left blank (null = none found)
  actionsGate: { remote: REMOTE_MODE, enabled: actionsEnabledHere() },
});

/** Settings ▸ Auto workflow model: the stored id + what the classifier will actually use
 *  (env override > stored catalog id > the Sonnet-class default). Async because the
 *  catalog is. */
async function autoModelState() {
  const models = await listModels('');
  const stored = storedAutoWorkflowModel();
  const model = resolveAutoModel(models, { setting: stored });
  const source = process.env[AUTO_MODEL_ENV]?.trim() ? 'env'
    : (stored && model.toLowerCase() === stored.toLowerCase()) ? 'settings' : 'default';
  return { autoWorkflowModel: stored, autoWorkflowModelEffective: { model, source } };
}

/** What "(default)" means for the Requirements interview row: the newest plain Opus at medium effort (A1-D8).
 *  Nothing while the requirements flag is off. */
async function requirementsInterviewState() {
  if (!flagEnabled('requirements')) return {};
  return { requirementsInterviewDefault: { model: (await requirementsModel(() => listModels(''))) ?? null, effort: DEFAULT_INTERVIEW_EFFORT } };
}
/** Settings ▸ PR description model: the stored id + what Generate with AI will actually
 *  use (stored catalog id > the Sonnet-class default). Async because the catalog is. */
async function prDescriptionModelState() {
  const stored = storedPrDescriptionModel();
  const { model, source } = resolvePrDescriptionModel(await listModels(''), { setting: stored });
  return { prDescriptionModel: stored, prDescriptionModelEffective: { model, source } };
}

/** Settings ▸ Agent generation model: the stored pair + what Generate will actually run on
 *  (the stored catalog model, else the CLI default). Async because the catalog is. */
async function agentGenModelState() {
  const stored = storedAgentGenModel();
  return { agentGenModel: stored, agentGenModelEffective: resolveAgentGenModel(withRole(stored, 'claude', 'agentGenModel'), await listModels('')) };
}

/** Models › Helper jobs › Run naming: the stored pair + what a suggestion will actually run on. */
async function namingModelState() {
  const stored = storedNamingModel();
  return { namingModel: stored, namingModelEffective: resolveNamingModel(withRole(stored, 'claude', 'namingModel'), await listModels(''), modelCostConfig) };
}

/** Models › Helper jobs › Command summaries: the stored pair + what a summary will actually run on. */
async function commandSummaryModelState() {
  const stored = storedCommandSummaryModel();
  return { commandSummaryModel: stored, commandSummaryModelEffective: resolveNamingModel(withRole(stored, 'claude', 'commandSummaryModel'), await listModels(''), modelCostConfig) };
}

// ---------------------------------------------------------------------------
// Instance lifecycle (`worca ui status|stop|restart`, src/core/ui-instance.mjs)
// ---------------------------------------------------------------------------
// `uiControl` is set by the boot block below when the server owns a port. Under
// test (app imported, no bind) it stays empty: /api/health still answers, and
// /api/shutdown refuses with 503 rather than exiting the test runner.
const uiControl = { token: null, onShutdown: null, startedAt: null };
const startedAtIso = () => uiControl.startedAt || null;

app.get('/api/health', (req, res) => {
  // Remote mode: it is the one unauthenticated route, so a caller from outside
  // the box learns only what it is, not the pid/bind/port/boot time.
  if (REMOTE_MODE && !isInContainer(req)) return res.json({ name: UI_HEALTH_NAME, version: PKG_VERSION });
  const addr = req.socket && req.socket.localPort;
  res.json({
    name: UI_HEALTH_NAME,
    version: PKG_VERSION,
    pid: process.pid,
    host: HOST,
    port: addr || PORT,
    startedAt: startedAtIso(),
  });
});

// CONTRACT §0: is git usable here, re-probed at most once a minute (U4: installing git needs no restart).
// A flip broadcasts the `git` frame through onGitChange.
app.get('/api/git', async (_req, res) => {
  const s = await gitState({ maxAgeMs: 60_000 });
  res.json({ available: s.available, version: s.version, reason: s.reason, checkedAt: s.checkedAt });
});

// Who this request is, for the header's "Signed in as" (identity.mjs). Attribution only.
// `shared`: a real per-person sign-in (Access or a trusted header), the one case where the UI
// shows people at all; a local install or a one-person WORCA_IDENTITY_NAME deployment shows none.
app.get('/api/whoami', (req, res) => {
  const who = resolveIdentity(req);
  res.json(who.source === 'local' ? { name: null, source: 'local', shared: false } : { ...who, shared: isSharedIdentity(who.source) });
});

// The signed-in person's model credentials, as the credential broker sees them
// (docs/credential-broker.md). Status only: which slots have a key, never a key.
// { enabled:false } with the broker off.
// OpenRouter's daily allowance of `:free` requests (src/core/openrouter-free.mjs), for the
// signed-in person with the credential broker, else for the install's key. The account menu's
// free-request row, the new-run warning and the Providers page read it; ?refresh=1 asks OpenRouter now.
app.get('/api/openrouter/free-daily', async (req, res) => {
  try {
    res.json(await freeDailyStatus({ person: currentBillTo(), force: req.query.refresh === '1' }));
  } catch (err) {
    res.status(500).json({ enabled: false, error: err && err.message ? err.message : String(err) });
  }
});

app.get('/api/credentials', async (req, res) => {
  if (!brokerEnabled()) return res.json({ enabled: false });
  try {
    try { await syncPluginSlots(); } catch { /* status below still answers */ }
    const info = await brokerInfo();
    const who = resolveIdentity(req);
    // Which slot each catalog model spends from: the pickers' "your key / no key" badges.
    const models = {};
    try {
      for (const m of await listModels()) {
        const r = modelSlot(m.id);
        if (r) models[m.id] = r.slot ? { slot: r.slot } : r.keyless ? { keyless: true } : { error: r.error };
      }
    } catch { /* badges are a nicety: an unreadable catalog leaves them off */ }
    const base = { enabled: true, mode: info.mode, keyPage: info.publicUrl || null, models };
    if (info.mode !== 'multi') return res.json({ ...base, person: null, slots: (await personSlots('local')).slots });
    if (!isSharedIdentity(who.source)) return res.json({ ...base, person: null, slots: [] });
    const r = await personSlots(who.name);
    res.json({ ...base, person: r.person, slots: r.slots });
  } catch (err) {
    res.status(502).json({ enabled: true, error: err && err.message ? err.message : String(err) });
  }
});

// ── Ask Worca tool relay (agent users, agent-pool.mjs) ───────────────────────────────
// When agents run under their own users, a chat's claude runs as the person's agent user,
// which cannot read worca's database. Its MCP child then only relays each JSON-RPC line
// here; the worca tools run in this process (createAskToolServer), in the chat owner's
// billing context. One token per turn, loopback callers only, dropped when the turn ends.
// set_away_now / set_run_away_mode: the parent's half, over the settings and THIS process's live runs.
const askAwaySwitch = createAwaySwitch({ liveRun: liveRunEntry, runs, emitChanged });
// B4: Ask's "I'm away" sets the asking person's own switch when per-person Away mode is on.
const askAwaySwitchFor = (person) => (awayPerPerson() && person && person !== 'local')
  ? createAwaySwitch({
    liveRun: liveRunEntry, runs, emitChanged,
    setToggle: async (v, o) => { if (!(await setPersonNightModeToggle(person, v, o))) await setNightModeToggle(v, o); },
    readToggle: () => nightModeToggleFor(person), readHereSince: () => nightModeHereSinceFor(person),
  })
  : askAwaySwitch;

// worca Chat P2 (U1, U4, R6–R10): the settings the chat may change, and the parent's half of its act-then-undo
// tools — the same in-process functions the HTTP routes call (applySettingsPatch, applyProjectSettingsPatch,
// pauseRun, resumeRun, stopRun, stopPausedPipeline, postDirection, scheduleVerb, the Away switch). Never a loopback.
const askSettingsQueue = createWriteQueue();
const askChatSettings = createSettingsRegistry({
  ...defaultSettingsRegistryDeps(),
  serial: askSettingsQueue,
  applyUser: (body) => applySettingsPatch(body),
  applyProject: (project, patch) => applyProjectSettingsPatch(project, patch),
});
const askChatActions = createChatActionHost({
  settings: askChatSettings,
  liveRun: (id) => liveRunEntry(id),
  findRow: (id) => findPipelineRowById(id),
  pauseRun: async (runId, by) => pauseRun(runId, by),
  // POST /api/resume's wording for an engine refusal (the run's own text names a CLI flag).
  resumeRun: async (pipelineId, opts) => {
    try { return await resumeRun(pipelineId, opts); } catch (err) {
      if (err && err.body && err.body.code === 'engine-refused') err.body = { ...err.body, error: engineRefusalFor(err.body.error, 'ui') };
      throw err;
    }
  },
  stopRun: (runId, by) => stopRun(runId, by),
  stopPausedPipeline: (pipelineId, by) => stopPausedPipeline(pipelineId, by),
  postDirection: (pipelineId, text, source) => postDirection(pipelineId, text, source),
  scheduleVerb: (verb, id, body, o) => scheduleVerb(verb, id, body, o),
  getSchedule: (id) => { const f = findScheduleItem(id); return f && f.kind === 'recurring' ? f.item : null; },
  awaySwitchFor: (person) => askAwaySwitchFor(person),
  awayStatusFor: (person) => askAwayStatusFor(person),
  prState: (id) => readPrState(id),
  prCardFacts: (row) => askPrCardFacts(row),
  serial: askSettingsQueue,
});

/** One turn's chat-action deps (startAskTurn): set_away_now / set_run_away_mode — the parent applies what the MCP child
 *  validated and hands back a revertible receipt when the status changed, on the asking person's own switch — and
 *  change_setting, pause_run, resume_run, propose_stop_run, send_direction, propose_pull_request plus the receipts of
 *  pause_schedule / resume_schedule, recorded as "<person> via worca chat". Named so a test pins the actor and person. */
function askChatTurnDeps(turnReader) {
  return {
    awaySwitch: (req) => askChatActions.awaySwitch(req, { actor: turnReader || 'local', person: turnReader }),
    // Shaper's two card tools need the thread (what it follows); every other kind is the chat action host's.
    chatAction: (req, o = {}) => (req && (req.kind === 'changes' || req.kind === 'route')
      ? askShapeAction(req, o.threadId || null)
      : askChatActions.apply(req, { actor: askActorFor(turnReader) })),
  };
}

/** The Away status a receipt shows for this person: the stored switch, or 'here' while an "I'm back" still counts.
 *  'here' is an input, not a stored status: "I'm back" = auto with hereSince set (settings.mjs setNightModeToggle), and
 *  hereSince stays stored after its away stretch ends — it counts only inside the stretch it was said in (describe.mjs
 *  'here-now'), so a stale one reads as 'auto'. */
function askAwayStatusFor(person) {
  const toggle = nightModeToggleFor(person);
  if (toggle !== 'auto') return toggle;
  const hereSince = nightModeHereSinceFor(person);
  if (hereSince == null) return 'auto';
  const { config } = resolveNightConfig({ user: nightModeSettings() || {} });
  return describeAwayMode({ config, toggle: 'auto', hereSince, now: Date.now() }).status === 'here-now' ? 'here' : 'auto';
}

/** The pull-request card's facts (CONTRACT §4) for a finished run's row: the branches, and the results summary's
 *  file and line counts when the run saved one (the numbers the Ship it dialog shows). path.join: Windows-safe. */
async function askPrCardFacts(row) {
  const isWs = row.target === 'workspace';
  const parse = (v) => { try { const o = JSON.parse(v || 'null'); return o && typeof o === 'object' ? o : null; } catch { return null; } };
  const branch = isWs
    ? Object.values((parse(row.workspace_meta) || {}).branches || {}).find((b) => b && b.feature) || {}
    : parse(row.branch) || {};
  let summary = null;
  try {
    const dir = await runDirForRow(row);
    const res = dir ? JSON.parse(await fsp.readFile(path.join(dir, 'results.json'), 'utf8')) : null;
    summary = res && res.summary && typeof res.summary === 'object' ? res.summary : null;
    // P5: a workspace run's Folder members ship in no pull request (their changes wait for Apply): count the Git members only
    const folder = isWs ? new Set(((parse(row.workspace_meta) || {}).projects || []).filter((p) => p && p.workMode === 'folder').map((p) => p.projectKey)) : null;
    if (summary && folder && folder.size && res.perProject && typeof res.perProject === 'object') {
      summary = { filesNew: 0, filesChanged: 0, linesAdded: 0, linesRemoved: 0 };
      for (const [k, v] of Object.entries(res.perProject)) if (!folder.has(k)) for (const f of Object.keys(summary)) summary[f] += Number(v?.summary?.[f]) || 0;
    }
  } catch { summary = null; }
  return {
    pipelineId: row.id,
    projectKey: isWs ? `workspaces/${row.workspace_key}` : row.project_key,
    ...(isWs && row.workspace_key ? { workspaceId: row.workspace_key } : {}),
    title: row.title || row.id,
    branch: branch.feature || null,
    ...(!isWs && branch.source ? { base: branch.source } : {}),
    ...(summary ? { filesChanged: (Number(summary.filesNew) || 0) + (Number(summary.filesChanged) || 0),
      additions: Number(summary.linesAdded) || 0, deletions: Number(summary.linesRemoved) || 0 } : {}),
  };
}

const askRelays = new Map();   // token -> { rpc, out, billTo, owner }

function askAgentRelay({ threadId, reader, web = null, engine = 'claude', model = null, skillRoot = null }) {
  const token = randomBytes(24).toString('base64url');
  const life = new AbortController();
  const entry = { out: [], billTo: currentBillTo(), owner: currentOwner() };
  // The tools run here, so this turn's web access rides a private env copy (never process.env itself);
  // the search key is read from worca's own environment, where it was set.
  // A locked-down turn's set skills (#635): this message's mount, one more read root for this relay (this turn) only.
  const env = { ...process.env, ...askWebMcpEnv(web), ...(lockedChatEngine(engine) ? { WORCA_ASK_ENGINE: engine, ...(typeof model === 'string' && model ? { WORCA_ASK_MODEL: model } : {}), ...(skillRoot ? { WORCA_ASK_SKILL_ROOT: skillRoot } : {}) } : {}) };
  entry.rpc = createAskToolServer({
    threadId, reader, signal: life.signal, env, write: (s) => { entry.out.push(s); },
    // The tools run in THIS process, which holds the live runs: get_run_diff can read a run
    // still in flight (its worktree against the pre-run checkpoint) before any patch is saved.
    extraDeps: {
      readLiveDiff: async (row) => {
        const live = liveRunEntry(row && row.id);
        if (!live || !live.orch || typeof live.orch.liveDiff !== 'function') return null;
        const out = await liveDiffOf(live).catch(() => null);
        return out && typeof out.patch === 'string' ? out.patch : null;
      },
      // Away mode on a live run (get_away_mode): its switch, mark and open question live only here.
      readLiveNight: (id) => {
        const live = liveRunEntry(id);
        if (!live || !live.orch) return null;
        const dir = live.projectDir || null;
        return { status: live.orch.state?.status ?? live.status ?? null, night: live.orch.state?.night || null, waiting: live.orch.pendingQuestion != null,
          projectDir: dir, projectKey: dir ? projectKey(dir) : null };
      },
      // Shaper (D7): here the tools see the live runs, so an open step's refusal reaches the model as the tool result.
      ...defaultShapeToolDeps({ threadId, live: (id) => liveSliceOf(id) }),
      // Corporate proxy: read in-process; Test is refused under agent isolation (relayProxyDeps).
      proxy: relayProxyDeps(),
    },
  });
  askRelays.set(token, entry);
  const port = server.address()?.port || PORT;
  return { url: `http://127.0.0.1:${port}/api/ask/relay`, token, dispose: () => { life.abort(); askRelays.delete(token); } };
}

app.post('/api/ask/relay', async (req, res) => {
  if (!isInContainer(req)) return res.status(403).json({ error: 'relay: loopback callers only' });
  const entry = askRelays.get(String(req.headers['x-worca-relay'] || ''));
  if (!entry) return res.status(403).json({ error: 'relay: unknown or finished turn' });
  const line = req.body && typeof req.body.line === 'string' ? req.body.line : null;
  if (line === null) return badRequest(res, 'relay: line is required');
  // One line at a time per turn (the child sends sequentially), so the output collected
  // between feed and idle is this line's answer.
  await withBillTo(entry.billTo, async () => {
    entry.out = [];
    await entry.rpc.feed(line);
    await entry.rpc.idle();
  }, { owner: entry.owner });
  res.json({ out: entry.out });
});

/**
 * Credential-broker preflight for starting work with known models (an Ask message, a run
 * started with an explicit model): refused up front, naming each missing key and the key
 * page, instead of the first spawn failing. In single mode the one set of keys is checked.
 * Never blocks on a broker that can't be asked.
 * @param {string[]} modelIds
 * @returns {Promise<string|null>} the refusal, or null to proceed
 */
async function brokerStartRefusal(req, modelIds) {
  if (!brokerEnabled() || !modelIds || !modelIds.length) return null;
  try {
    try { await syncPluginSlots(); } catch { /* the spawn says why */ }
    const info = await brokerInfo();
    let person = 'local';
    if (info.mode === 'multi') {
      const who = resolveIdentity(req);
      if (!isSharedIdentity(who.source)) return null;
      person = who.name;
    }
    const r = missingCredentials(modelIds, modelSlot, (await personSlots(person)).slots || []);
    if (!r.missing.length && !r.errors.length) return null;
    const one = r.missing.length === 1 && !r.errors.length ? r.missing[0] : null;
    const where = info.publicUrl ? ` Add it on the key page (${info.publicUrl}), then try again.` : ' Add it to the credential broker, then try again.';
    if (one) {
      return one.state === 'invalid'
        ? `Your ${one.label} was rejected by the provider.${where}`
        : `You haven't added your ${one.label} yet, and ${one.models.join(', ')} needs it.${where}`;
    }
    return `Can't start: ${describeMissing(r, info.publicUrl)}`;
  } catch {
    return null;
  }
}

/** Constant-time bearer check; `expected` is the boot-time token from ui.json. */
function bearerMatches(header, expected) {
  if (!expected || typeof header !== 'string') return false;
  const m = /^Bearer\s+(\S+)$/i.exec(header.trim());
  if (!m) return false;
  const a = Buffer.from(m[1]);
  const b = Buffer.from(expected);
  return a.length === b.length && timingSafeEqual(a, b);
}

// ---------------------------------------------------------------------------
// Graceful drain (B2, src/core/drain.mjs). Runs on every stop of a server started with
// `worca ui` (SIGTERM, SIGINT, POST /api/shutdown) before the rest of the shutdown, and on
// POST /api/drain. From the first call on, the server starts nothing new: new runs, resumes and
// scheduled starts answer 503 `draining`. Every active run pauses with the reason 'drain' (its
// resume point is saved as on any pause), and the drain waits up to WORCA_DRAIN_TIMEOUT_MS for
// those pauses to land. A drain is one-way: only a restart accepts work again.
// ---------------------------------------------------------------------------
const DRAIN = { on: false, startedAt: null, promise: null, result: null };
const DRAIN_REFUSAL = Object.freeze({ error: 'draining', message: 'worca is stopping: start this again once it is back' });
const DRAIN_POLL_MS = 200;

/** Live pipeline-run entries a drain must see paused (or settled) before the server exits. */
function drainActiveEntries() {
  return [...runs.values()].filter((e) => typeof e.orch?.pauseForDrain === 'function'
    && DRAIN_ACTIVE_STATUSES.has(String(e.orch.state?.status || e.status || '')));
}

/**
 * Pause every active run for a stop and wait (bounded) for the pauses to land. Idempotent: a
 * second call joins the first. Resolves { paused, remaining, waitedMs } and never rejects.
 * A run still starting is paused as soon as it is running, within the same bound.
 */
function drainServer({ timeoutMs = drainTimeoutMs(), reason = 'stop' } = {}) {
  if (DRAIN.promise) return DRAIN.promise;
  DRAIN.on = true;
  DRAIN.startedAt = Date.now();
  DRAIN.promise = (async () => {
    const pausedIds = new Set();
    const pauseNow = () => {
      for (const e of drainActiveEntries()) {
        if (pausedIds.has(e.id) || e.orch.state?.status !== 'running') continue;
        try {
          if (e.orch.pauseForDrain()) {
            pausedIds.add(e.id);
            e.status = 'pausing';
            resolvePending(e, { reason: 'paused' });
            syncKeepAwake();
          }
        } catch (err) { console.error(`[worca-ui] drain: could not pause ${e.pipelineId || e.id}: ${err?.message || err}`); }
      }
    };
    const active = drainActiveEntries().length;
    if (active) console.log(`[worca-ui] drain (${reason}): pausing ${active} active run(s), waiting up to ${Math.round(timeoutMs / 1000)} s`);
    pauseNow();
    const deadline = DRAIN.startedAt + timeoutMs;
    while (drainActiveEntries().length && Date.now() < deadline) {
      await new Promise((r) => setTimeout(r, DRAIN_POLL_MS));
      pauseNow();
    }
    const remaining = drainActiveEntries().length;
    const result = { paused: pausedIds.size, remaining, waitedMs: Date.now() - DRAIN.startedAt };
    if (active || remaining) {
      console.log(`[worca-ui] drain: ${result.paused} run(s) paused${remaining ? `, ${remaining} still active after ${Math.round(timeoutMs / 1000)} s (they come back interrupted)` : ''}`);
    }
    if (pausedIds.size) emitChanged('pipelines-changed', 'updated');
    DRAIN.result = result;
    return result;
  })().catch((err) => {
    console.error(`[worca-ui] drain failed: ${err?.message || err}`);
    return { paused: 0, remaining: drainActiveEntries().length, waitedMs: Date.now() - DRAIN.startedAt };
  });
  return DRAIN.promise;
}

/**
 * B3: after boot maintenance, resume the runs a drain paused (by default; WORCA_AUTO_RESUME=0 turns
 * it off) and, with WORCA_AUTO_RESUME=1, also the runs this start found dead under a previous process
 * (`interruptedIds`), each as the person who last started or resumed it. Resumes go through resumeRun's whole guard chain (budget gates
 * included); a refusal is logged and leaves the run waiting for a person.
 */
async function autoResumeOnBoot({ interruptedIds = [], env = process.env, mock = isTruthy(process.env.WORCA_MOCK ?? process.env.ORCH_MOCK) } = {}) {
  const mode = autoResumeMode(env);
  if (mode === 'off') return { enabled: false, resumed: [], failed: [] };
  const rows = getDb().prepare(`SELECT id, status, started_by, archived_at, resume_point FROM pipelines
    WHERE status IN ('paused', 'interrupted') AND archived_at IS NULL ORDER BY started_at ASC`).all()
    .map((r) => { let rp = null; try { rp = r.resume_point ? JSON.parse(r.resume_point) : null; } catch { /* unreadable point */ } return { ...r, resumePoint: rp }; });
  const picks = autoResumeCandidates(rows, {
    interruptedNow: new Set(interruptedIds),
    hasResumeTicket: (id) => resumeTicketsFor(id).length > 0,
    includeInterrupted: mode === 'all',
  });
  const resumed = [];
  const failed = [];
  for (const p of picks) {
    try {
      const out = await resumeRun(p.pipelineId, { by: p.by, mock });
      resumed.push({ ...p, runId: out?.runId || null });
      appendAuditById(p.pipelineId, `Pipeline resumed automatically after ${p.why === 'drain' ? 'a restart' : 'an interruption'}${byActor(p.by)}.`, { actor: p.by });
    } catch (err) {
      failed.push({ ...p, error: (err instanceof ResumeError && err.body?.error) || err?.message || String(err) });
    }
  }
  if (resumed.length) console.log(`[worca-ui] auto-resume: resumed ${resumed.length} run(s): ${resumed.map((r) => r.pipelineId).join(', ')}`);
  for (const f of failed) console.warn(`[worca-ui] auto-resume: ${f.pipelineId} stays ${f.why === 'drain' ? 'paused' : 'interrupted'}: ${f.error}`);
  if (resumed.length) emitChanged('pipelines-changed', 'updated');
  return { enabled: true, resumed, failed };
}

// POST /api/drain: drain without exiting (a platform about to stop the container asks first, so
// the stop itself is quick). From inside the container, or with WORCA_HEARTBEAT_TOKEN as Bearer.
app.post('/api/drain', async (req, res) => {
  const hbToken = String(process.env.WORCA_HEARTBEAT_TOKEN || '').trim();
  if (!isInContainer(req) && !(hbToken && bearerMatches(req.headers.authorization, hbToken))) {
    return res.status(403).json({ error: 'forbidden: drain only from inside the container or with the heartbeat token' });
  }
  const result = await drainServer({ reason: 'request' });
  res.json({ ok: true, draining: true, ...result });
});

app.post('/api/shutdown', (req, res) => {
  if (!uiControl.token || typeof uiControl.onShutdown !== 'function') {
    return res.status(503).json({ error: 'shutdown is only available on a server started with `worca ui`' });
  }
  if (!bearerMatches(req.headers.authorization, uiControl.token)) {
    return res.status(401).json({ error: 'shutdown requires the bearer token from the instance file' });
  }
  res.status(202).json({ ok: true, pid: process.pid });
  // Answer first, exit on the next tick so the 202 actually leaves the socket.
  setImmediate(() => uiControl.onShutdown('request'));
});

app.get('/api/settings', async (req, res) => {
  const person = awayPersonOf(req);   // B4: a signed-in person sees their own Away switch
  res.json({ ...settingsState(), ...(person ? { nightModeToggle: nightModeToggleFor(person), nightModePerPerson: person } : {}), ...(await autoModelState()), ...(await prDescriptionModelState()), ...(await agentGenModelState()), ...(await namingModelState()), ...(await commandSummaryModelState()), ...(await requirementsInterviewState()), chat: chatPrefs(), app: APP_INFO });
});

// GET  /api/app/version       → { current, latest, status, checkedAt, enabled, links } (issue #841);
//                                status 'source' on a git checkout (no npm request, no update links).
// POST /api/app/version/check → the same, re-checking npm unless the last try is under a minute old.
// Read-only: nothing here installs or restarts anything. Failures read as status 'unknown'.
app.get('/api/app/version', async (req, res) => {
  res.set('Cache-Control', 'no-store').json(versionPayload(await updateChecker.status()));
});
app.post('/api/app/version/check', async (req, res) => {
  res.set('Cache-Control', 'no-store').json(versionPayload(await updateChecker.status({ force: true })));
});

// Manual update (issue #841). GET reads only; POST asks the `worca ui` supervisor to install: it
// writes <worcaHome>/update.json, drains like a stop, and exits UPDATE_EXIT_CODE. Nothing installs here.
app.get('/api/app/update', async (req, res) => {
  const elig = await currentUpdateEligibility(req);
  const list = updateCheckEnabled() ? await versionLister.get() : versionLister.peek();
  const rc = list?.distTags?.rc || null;
  res.set('Cache-Control', 'no-store').json({
    ...elig, current: RUNNING_VERSION, distTags: list?.distTags || null,
    rcNewer: !!(rc && parseVersion(PKG_VERSION) && compareVersions(parseVersion(rc), parseVersion(PKG_VERSION)) > 0),
    autoRestartMin: AUTO_RESTART_MIN, startCommand: startCommand(updatePort()), lastResult: lastUpdateResult(),
  });
});
app.get('/api/app/update/versions', async (req, res) => {
  const list = await versionLister.get({ force: req.query.refresh === '1' });
  if (!list) return res.status(502).json({ error: 'Could not load the version list from npm. Try again in a moment.', code: 'VERSIONS_UNAVAILABLE' });
  res.set('Cache-Control', 'no-store').json({ current: RUNNING_VERSION, distTags: list.distTags, versions: annotateVersions(list, PKG_VERSION) });
});
app.get('/api/app/update/preview', async (req, res) => {
  // Lists run titles: answer only this Worca's own pages, never an agent.
  if (!terminalSameOrigin(req) || agentMayBeCaller(req)) return res.status(403).json({ error: 'Updates only answer pages served by this Worca.', code: 'UPDATE_CROSS_ORIGIN' });
  const target = canonicalVersion(req.query.version);
  if (!target) return res.status(400).json({ error: 'Pick a version from the list.', code: 'UPDATE_BAD_VERSION' });
  res.set('Cache-Control', 'no-store').json({ target, autoRestart: canAutoRestart(target), startCommand: startCommand(updatePort()), ...updatePreview() });
});
app.post('/api/app/update', async (req, res) => {
  if (!updateCallerOk(req, res)) return;
  if (updateRequested || DRAIN.on) return res.status(503).json({ error: 'Worca is already stopping.', code: 'UPDATE_IN_PROGRESS' });
  const target = canonicalVersion(req.body?.version);
  if (!target) return res.status(400).json({ error: 'Pick a version from the list.', code: 'UPDATE_BAD_VERSION' });
  if (target === RUNNING_VERSION) return res.status(400).json({ error: `Worca ${target} is already running.`, code: 'UPDATE_SAME_VERSION' });
  const elig = await currentUpdateEligibility(req);
  if (!elig.canUpdate) return res.status(409).json({ error: elig.message, code: 'UPDATE_UNAVAILABLE', reason: elig.reason });
  const list = await versionLister.get();
  if (!list) return res.status(502).json({ error: 'Could not reach the npm registry. Try again in a moment.', code: 'VERSIONS_UNAVAILABLE' });
  if (!findListedVersion(list, target)) return res.status(400).json({ error: `@worca/app@${target} is not on npm.`, code: 'UPDATE_BAD_VERSION' });
  if (updateRequested || DRAIN.on) return res.status(503).json({ error: 'Worca is already stopping.', code: 'UPDATE_IN_PROGRESS' });
  const autoRestart = canAutoRestart(target); const port = updatePort();
  updateRequested = true;
  try {
    writeUpdateRecord({ state: 'requested', from: RUNNING_VERSION, to: target, autoRestart, port, requestedAt: new Date().toISOString(), pid: process.pid });
  } catch (err) {
    updateRequested = false;
    return res.status(500).json({ error: `Could not record the update request: ${err.message}`, code: 'UPDATE_RECORD_FAILED' });
  }
  console.log(`[worca] update to ${target} requested; draining and handing over to worca ui`);
  res.status(202).json({ ok: true, target, autoRestart, startCommand: startCommand(port) });
  setImmediate(() => uiControl.onShutdown('update'));
});
app.post('/api/app/update/dismiss', (req, res) => {
  if (!terminalSameOrigin(req) || agentMayBeCaller(req)) return res.status(403).json({ error: 'Not from here.', code: 'UPDATE_CROSS_ORIGIN' });
  const rec = readUpdateRecord();
  if (rec && (rec.state === 'failed' || rec.state === 'installed')) writeUpdateRecord({ ...rec, state: 'dismissed' });
  res.json({ ok: true });
});

app.get('/api/budget', (_req, res) => {
  const budget = budgetStatus();
  // The account menu's spend card ("Saved") rides on this snapshot (money-saved design §10).
  // Additive and best-effort: a failed savings read must never cost the gate figures the
  // New-view Start button and every cost banner key on, so it degrades to nulls instead.
  let savings = { windowHumanHours: null, windowSavedUsd: null };
  try { savings = budgetWindowSavings(budget); } catch { /* keep the nulls */ }
  res.json({ ...budget, ...savings });
});

/**
 * The Models page's utility pickers (title, Auto classifier, PR description, memory defragment,
 * agent generation, run naming, workspace scan) are Claude's slots (cascading-settings-design.md D10/§3.1): a Codex or Cursor id there is
 * a 400 that names it. A Codex run's utility jobs run on Codex's own default for now.
 * @throws {Error}
 */
function refuseNonClaudeUtilityModel(key, value) {
  const id = typeof value === 'string' ? value.trim()
    : (value && typeof value === 'object' ? String(value.model ?? value.scanModel ?? '').trim() : '');
  const harnesses = id ? enginesOfModel(id) : null;   // null: no catalog knows the id — allowed, as today
  if (harnesses && !harnesses.includes('claude')) throw new Error(`${key}: "${id}" runs on ${harnesses.map(engineLabel).join(' or ')}. This setting picks a model Claude Code can run`);
}

app.post('/api/settings', async (req, res) => {
  const body = req.body || {};
  const has = (k) => Object.prototype.hasOwnProperty.call(body, k);
  // D4: actions.editor / actions.terminal are command paths the built-ins route spawns as the server user.
  if (has('actions') && agentMayBeCaller(req)) return refuseAgentCaller(res);
  // Hosted with browsing limited: the Worca root and projects root move only within Worca's own
  // folders (both widen what can be browsed, and the setters probe the path). Clearing is fine.
  if (!(await requireFsAllowed(req, res, [has('root') ? normalizeProjectPath(body.root) : null,
    has('projectsRoot') ? normalizeProjectPath(body.projectsRoot) : null]))) return;
  try {
    const { actionsWarnings } = await applySettingsPatch(body, { person: awayPersonOf(req) });
    res.json({ ...settingsState(), ...(await autoModelState()), ...(await prDescriptionModelState()), ...(await agentGenModelState()), ...(await namingModelState()), ...(await commandSummaryModelState()), ...(await requirementsInterviewState()), chat: chatPrefs(),
      ...(actionsWarnings ? { actionsWarnings } : {}) });
  } catch (err) {
    // 400 with the user's words and, when known, the body path of the bad field (#555).
    const { error, field } = settingsErrorReply(err, err && err.settingsCtx);
    return res.status(400).json({ error, ...(field ? { field } : {}) });
  }
});

/** The catalog checks on an asserted modelRoles patch, shared by POST /api/settings and setup apply (A18).
 *  Returns the patch with each model rewritten to the catalog's canonical id. `pending`: the catalog rows
 *  this setup apply's own imports will create (pendingImportIds); POST /api/settings passes none. */
async function checkModelRolesPatch(patch, { pending = [] } = {}) {
  const items = [];
  // Model and harness only: the role effort is mapped when used (effortOn), never refused here (A7).
  for (const [engine, roles] of Object.entries(patch)) for (const [role, value] of Object.entries(roles)) if (value) items.push({ id: `modelRoles.${engine}.${role}`, engine, value: { model: value.model } });
  await assertSlotModels(items, { pending });
  // Store the catalog's canonical id (A8), so every consumer matches the same spelling; a pending id keeps the
  // spelling its import will write.
  if (items.length) {
    const models = await listModels('');
    for (const roles of Object.values(patch)) for (const value of Object.values(roles)) {
      if (!value) continue;
      const lc = value.model.toLowerCase();
      const hit = models.find((m) => m?.id?.toLowerCase() === lc) || pending.find((p) => p.id.toLowerCase() === lc);
      if (hit) value.model = hit.id;
    }
  }
  return patch;
}

/**
 * POST /api/settings' body without the request: validate every present key before any write, write them (root
 * first), then the broadcasts. Shared with Ask's change_setting and its Revert (worca Chat P2), which send ONE known
 * key — never an empty body: a body naming no known key clears root (the legacy contract below).
 * @param {object} body  the partial settings patch
 * @param {{person?: string|null}} [o]  B4: whose own Away switch nightModeToggle writes (null = the instance switch)
 * @returns {Promise<{actionsWarnings: object|null}>}
 * @throws {Error} the first refused value (err.settingsCtx names the field)
 */
async function applySettingsPatch(body, { person = null } = {}) {
  const has = (k) => Object.prototype.hasOwnProperty.call(body, k);
  const hasBudgetKey = has('pipelineCostLimitUsd') || has('totalCostLimitUsd') || has('costLimitResetPeriod');
  const hasHumanRateKey = has('humanRateUsdPerHour');
  const hasAskKey = has('askMaxTurns') || has('askMaxBudgetUsd');
  const hasAskWeb = has('askWeb');                // null clears back to unset (a team default applies)
  const hasSmartNaming = has('smartNaming');      // null clears the stored block
  const hasDebugSpawnKey = has('debugSpawnEnabled');
  const hasKeepAwakeKey = has('keepAwake');
  const hasLimitResumeKey = has('resumeAfterUsageLimit');
  const hasAutoPrDescKey = has('autoGeneratePrDescription');
  const hasUpdateCheckKey = has('updateCheck');
  const hasTitleModelKey = has('titleModel');
  const hasHideBuiltinKey = has('hideBuiltinModels');
  const hasThemeKey = has('theme');
  const hasUiLevelKey = has('uiLevel');
  const hasFlagsKey = has('flags');
  const hasAutoKey = has('autoWorkflowModel');
  const hasNightKey = has('nightMode') || has('nightModeToggle');
  const autoModels = hasAutoKey ? await listModels('') : null;
  const hasPrDescKey = has('prDescriptionModel');
  const prDescModels = hasPrDescKey ? (autoModels || await listModels('')) : null;
  // Settings › Memory: the defragment { model, effort } pair, checked against the same
  // project-less catalog the Settings pickers offer (a run re-checks it against its own).
  const hasMemoryDefragKey = has('memoryDefrag');
  const defragModels = hasMemoryDefragKey ? (autoModels || await listModels('')) : null;
  // The agent wizard's Generate pair: agent generation has no project, so the project-less catalog.
  const hasAgentGenKey = has('agentGenModel');
  const agentGenModels = hasAgentGenKey ? (autoModels || defragModels || await listModels('')) : null;
  const hasNamingModelKey = has('namingModel');
  const namingModels = hasNamingModelKey ? (autoModels || defragModels || agentGenModels || await listModels('')) : null;
  const hasCommandSummaryModelKey = has('commandSummaryModel');
  const csModels = hasCommandSummaryModelKey ? (autoModels || defragModels || agentGenModels || namingModels || await listModels('')) : null;
  const hasWorkspaceScanKey = has('workspaceScan');
  const hasRunEngineKey = has('runEngine');
  const hasExecEnvKey = has('execEnv');
  const e2bIntKeys = ['e2bMaxSandboxes', 'e2bMaxWaitMin'].filter((k) => has(k));
  const hasStepModelsKey = has('stepModels');
  const hasModelRolesKey = has('modelRoles');
  const hasUtilityModelsKey = has('utilityModels');
  const hasAskEngineKey = has('askEngine');
  const hasAskModelsKey = has('askModels');
  const hasRequirementsInterviewKey = has('requirementsInterview') && flagEnabled('requirements');   // ignored while the flag is off
  const hasActionsKey = has('actions');
  const hasNetworkWaitKey = has('networkWait');
  const wsScanModels = hasWorkspaceScanKey ? (autoModels || defragModels || await listModels('')) : null;
  // #422: the title model is a SELECT over the catalog, so an id that is not a
  // catalog member is a client bug (or a stale option) — refuse it here rather
  // than store an id resolveModelEnv could never route.
  const titleModelInput = hasTitleModelKey ? (body.titleModel ?? '') : undefined;
  // Normalize the budget keys first, then validate them as a SET before ANY write.
  // Each setter persists on its own, so a two-key POST whose second key is invalid
  // used to answer 400 with the first key already on disk, no budget-changed
  // emitted, and a client (which early-returns on !res.ok) still painting its
  // pre-save values over a half-applied settings file.
  const budget = {};
  if (has('pipelineCostLimitUsd')) budget.pipelineCostLimitUsd = body.pipelineCostLimitUsd ?? '';
  if (has('totalCostLimitUsd')) budget.totalCostLimitUsd = body.totalCostLimitUsd ?? '';
  if (has('costLimitResetPeriod')) {
    budget.costLimitResetPeriod = typeof body.costLimitResetPeriod === 'string' ? body.costLimitResetPeriod : '';
  }
  // Ask Worca per-turn guards (ask-worca-design.md §6.9): same set-validation
  // discipline. `null` is a VALUE for askMaxBudgetUsd (no cap) and must survive
  // normalisation; only undefined becomes a clear.
  const ask = {};
  if (has('askMaxTurns')) ask.askMaxTurns = body.askMaxTurns ?? '';
  if (has('askMaxBudgetUsd')) ask.askMaxBudgetUsd = body.askMaxBudgetUsd === undefined ? '' : body.askMaxBudgetUsd;
  {   // was the route's try: a refusal now reaches the caller (the route maps it to 400, the chat to a notice)
    for (const key of ['titleModel', 'autoWorkflowModel', 'prDescriptionModel', 'memoryDefrag', 'agentGenModel', 'namingModel', 'commandSummaryModel', 'workspaceScan', ...(hasRequirementsInterviewKey ? ['requirementsInterview'] : [])]) {
      if (has(key)) asSettingsField(key, () => refuseNonClaudeUtilityModel(key, body[key]));
    }
    // Each validator / setter that can refuse a value runs tagged with the body key it checks,
    // so the 400 can name the field (#555). Every argument is exactly as before. With no budget
    // or ask key the object is {}, which both set-validators accept, so the guards change nothing.
    // assertCostLimitInputs and assertAskLimitInputs name the failing key first ("askMaxTurns must…").
    if (hasBudgetKey) {
      try { assertCostLimitInputs(budget); } catch (e) {
        e.settingsCtx = ['pipelineCostLimitUsd', 'totalCostLimitUsd', 'costLimitResetPeriod'].find((k) => String(e.message).startsWith(k)) || 'pipelineCostLimitUsd';
        throw e;
      }
    }
    if (hasHumanRateKey) asSettingsField('humanRateUsdPerHour', () => assertHumanRateInput(body.humanRateUsdPerHour ?? ''));
    if (hasAskKey) {
      try { assertAskLimitInputs(ask); } catch (e) {
        e.settingsCtx = ['askMaxTurns', 'askMaxBudgetUsd'].find((k) => String(e.message).startsWith(k)) || 'askMaxTurns';
        throw e;
      }
    }
    if (hasAskWeb && body.askWeb !== null) asSettingsField('askWeb', () => assertAskWebInput(body.askWeb));
    if (hasSmartNaming && body.smartNaming !== null) asSettingsField('smartNaming', () => assertSmartNamingInput(body.smartNaming));
    if (hasDebugSpawnKey) asSettingsField('debugSpawnEnabled', () => assertDebugSpawnInput(body.debugSpawnEnabled));
    if (hasLimitResumeKey) asSettingsField('resumeAfterUsageLimit', () => assertResumeAfterUsageLimitInput(body.resumeAfterUsageLimit));
    if (hasAutoPrDescKey) asSettingsField('autoGeneratePrDescription', () => assertAutoGeneratePrDescriptionInput(body.autoGeneratePrDescription));
    if (hasUpdateCheckKey) asSettingsField('updateCheck', () => assertUpdateCheckInput(body.updateCheck));
    if (hasTitleModelKey) asSettingsField('titleModel', () => {
      assertTitleModelInput(titleModelInput);
      if (titleModelInput !== '' && titleModelInput !== null && !catalogHasModel(titleModelInput)) {
        throw new Error(`unknown model ${JSON.stringify(String(titleModelInput))} — pick one from the catalog`);
      }
    });
    if (hasHideBuiltinKey) asSettingsField('hideBuiltinModels', () => assertHideBuiltinModelsInput(body.hideBuiltinModels));
    if (hasThemeKey) asSettingsField('theme', () => assertThemeInput(body.theme));
    if (hasUiLevelKey) asSettingsField('uiLevel', () => assertUiLevelInput(body.uiLevel));
    if (hasAutoKey) asSettingsField('autoWorkflowModel', () => assertAutoWorkflowModelInput(body.autoWorkflowModel ?? '', autoModels));
    if (hasPrDescKey) asSettingsField('prDescriptionModel', () => assertPrDescriptionModelInput(body.prDescriptionModel ?? '', prDescModels));
    if (hasMemoryDefragKey) asSettingsField('memoryDefrag', () => assertMemoryDefragModelInput(body.memoryDefrag, defragModels));
    if (hasAgentGenKey) asSettingsField('agentGenModel', () => assertAgentGenModelInput(body.agentGenModel, agentGenModels));
    if (hasNamingModelKey) asSettingsField('namingModel', () => assertNamingModelInput(body.namingModel, namingModels));
    if (hasCommandSummaryModelKey) asSettingsField('commandSummaryModel', () => assertCommandSummaryModelInput(body.commandSummaryModel, csModels));
    if (hasWorkspaceScanKey) asSettingsField('workspaceScan', () => assertWorkspaceScanInput(body.workspaceScan, wsScanModels));
    if (hasRunEngineKey) asSettingsField('runEngine', () => assertRunEngineInput(body.runEngine));
    if (hasExecEnvKey) asSettingsField('execEnv', () => assertExecEnvInput(body.execEnv));
    for (const k of e2bIntKeys) asSettingsField(k, () => assertE2bIntInput(k, body[k]));
    if (hasAskEngineKey) asSettingsField('askEngine', () => assertAskEngineInput(body.askEngine));
    if (hasRequirementsInterviewKey) await asSettingsField('requirementsInterview', async () => {
      const v = assertRequirementsInterviewInput(body.requirementsInterview);
      if (v?.model) await assertSlotModels([{ id: 'requirementsInterview', engine: 'claude', value: v }]);
    });
    if (hasAskModelsKey) await asSettingsField('askModels', async () => {
      const patch = assertAskModelsInput(body.askModels);
      await assertSlotModels(Object.entries(patch).filter(([, value]) => value).map(([engine, value]) => ({ id: `askModels.${engine}`, engine, value })));
    });
    if (hasStepModelsKey) await asSettingsField('stepModels', async () => {
      const patch = assertStepModelsInput(body.stepModels);
      const items = [];
      for (const [engine, roles] of Object.entries(patch)) for (const [role, value] of Object.entries(roles)) if (value) items.push({ id: `stepModels.${engine}.${role}`, engine, value });
      await assertSlotModels(items);
    });
    let modelRolesPatch = null;
    if (hasModelRolesKey) await asSettingsField('modelRoles', async () => {
      modelRolesPatch = await checkModelRolesPatch(assertModelRolesInput(body.modelRoles));
    });
    if (hasUtilityModelsKey) await asSettingsField('utilityModels', async () => {
      const patch = assertUtilityModelsInput(body.utilityModels); const items = [];
      for (const [engine, jobs] of Object.entries(patch)) for (const [job, value] of Object.entries(jobs)) if (value) items.push({ id: `utilityModels.${engine}.${job}`, engine, value });
      await assertSlotModels(items);
    });
    if (has('nightMode') && body.nightMode !== null) asSettingsField('nightMode', () => {
      const { __unset, ...patch } = body.nightMode && typeof body.nightMode === 'object' && !Array.isArray(body.nightMode) ? body.nightMode : { __invalid: true };
      if (patch.__invalid) throw new Error('nightMode must be an object or null');
      if (__unset !== undefined && !Array.isArray(__unset)) throw new Error('nightMode.__unset must be a list of field names');
      validateNightPatch(patch);
    });
    if (has('nightModeToggle')) asSettingsField('nightModeToggle', () => assertNightModeToggleInput(body.nightModeToggle));
    if (hasActionsKey) asSettingsField('actions', () => assertActionsInput(body.actions));
    if (hasKeepAwakeKey) asSettingsField('keepAwake', () => assertKeepAwakeInput(body.keepAwake));
    if (has('sync')) asSettingsField('sync', () => assertSyncSettingsInput(body.sync));
    if (hasNetworkWaitKey) asSettingsField('networkWait', () => assertNetworkWaitInput(body.networkWait));
    if (hasFlagsKey) asSettingsField('flags', () => checkFlags(body.flags));   // validate + cascade dry run, before anything is written
    if (has('tagDimensions')) asSettingsField('tagDimensions', () => {
      const { errors } = normaliseDimensions(body.tagDimensions ?? []);
      if (errors.length) throw Object.assign(new Error(errors[0]), { code: 'BAD_TAG_DIMENSIONS' });
    });
    if (has('enforceTags')) asSettingsField('enforceTags', () => {
      if (typeof body.enforceTags !== 'boolean') throw Object.assign(new Error('enforceTags must be true or false'), { code: 'BAD_ENFORCE_TAGS' });
    });
    // Root first: it is the one key whose setter can still fail AFTER the asserts
    // above (an unusable path), so every other key's write must come after it or
    // a mixed POST would answer 400 with those keys already applied on disk.
    // Legacy contract: a POST that names NO known key clears root; the known
    // keys live beside their setters (SETTINGS_POST_KEYS), not in a list here.
    if (has('root') || !SETTINGS_POST_KEYS.some(has)) {
      await asSettingsField('root', () => setWorcaRoot(typeof body.root === 'string' ? body.root : ''));
    }
    if (has('chat')) await asSettingsField('chat', () => setChatPrefs(body.chat));
    if (has('projectsRoot')) {
      await asSettingsField('projectsRoot', () => setProjectsRoot(typeof body.projectsRoot === 'string' ? body.projectsRoot : ''));
    }
    if (has('pipelineCostLimitUsd')) await setPipelineCostLimitUsd(budget.pipelineCostLimitUsd);
    if (has('totalCostLimitUsd')) await setTotalCostLimitUsd(budget.totalCostLimitUsd);
    if (has('costLimitResetPeriod')) await setCostLimitResetPeriod(budget.costLimitResetPeriod);
    if (hasHumanRateKey) await setHumanRateUsdPerHour(body.humanRateUsdPerHour ?? '');
    if (has('askMaxTurns')) await setAskMaxTurns(ask.askMaxTurns);
    if (has('askMaxBudgetUsd')) await setAskMaxBudgetUsd(ask.askMaxBudgetUsd);
    if (hasAskWeb) await setAskWeb(body.askWeb);
    if (hasSmartNaming) await setSmartNaming(body.smartNaming);
    if (hasDebugSpawnKey) await setDebugSpawnEnabled(body.debugSpawnEnabled);
    if (hasKeepAwakeKey) { await setKeepAwake(body.keepAwake); syncKeepAwake(); }
    if (hasLimitResumeKey) await setResumeAfterUsageLimit(body.resumeAfterUsageLimit);
    if (hasAutoPrDescKey) await setAutoGeneratePrDescription(body.autoGeneratePrDescription);
    if (hasUpdateCheckKey) {
      await setUpdateCheck(body.updateCheck);
      if (body.updateCheck === false) updateChecker.clear();   // back on = a fresh check, never the old answer
    }
    if (hasTitleModelKey) await setTitleModel(titleModelInput);
    if (hasHideBuiltinKey) await setHideBuiltinModels(body.hideBuiltinModels);
    if (hasThemeKey) await setTheme(body.theme);
    if (hasUiLevelKey) await setUiLevel(body.uiLevel);
    if (hasFlagsKey) await asSettingsField('flags', () => setFlags(body.flags));   // same path as PATCH /api/flags (it broadcasts `flags`)
    if (hasAutoKey) await setAutoWorkflowModel(body.autoWorkflowModel ?? '', { models: autoModels });
    if (hasPrDescKey) await setPrDescriptionModel(body.prDescriptionModel ?? '', { models: prDescModels });
    if (hasMemoryDefragKey) await setMemoryDefragModel(body.memoryDefrag, { models: defragModels });
    if (hasAgentGenKey) await setAgentGenModel(body.agentGenModel, { models: agentGenModels });
    if (hasNamingModelKey) await setNamingModel(body.namingModel, { models: namingModels });
    if (hasCommandSummaryModelKey) await setCommandSummaryModel(body.commandSummaryModel, { models: csModels });
    if (hasWorkspaceScanKey) await setWorkspaceScanModels(body.workspaceScan, { models: wsScanModels });
    if (hasRunEngineKey) await asSettingsField('runEngine', () => setRunEngineSetting(body.runEngine));
    if (hasExecEnvKey) await asSettingsField('execEnv', () => setExecEnvSetting(body.execEnv));
    for (const k of e2bIntKeys) await asSettingsField(k, () => setE2bIntSetting(k, body[k]));
    if (hasStepModelsKey) await asSettingsField('stepModels', () => setStepModels(body.stepModels));
    if (hasModelRolesKey) await asSettingsField('modelRoles', () => setModelRoles(modelRolesPatch));
    if (hasUtilityModelsKey) await asSettingsField('utilityModels', () => setUtilityModels(body.utilityModels));
    if (hasAskEngineKey) await asSettingsField('askEngine', () => setAskEngineSetting(body.askEngine));
    if (hasAskModelsKey) await asSettingsField('askModels', () => setAskModels(body.askModels));
    if (hasRequirementsInterviewKey) await asSettingsField('requirementsInterview', () => setRequirementsInterview(body.requirementsInterview));
    if (has('schedule')) await asSettingsField('schedule', () => setScheduleDefaults(body.schedule && typeof body.schedule === 'object' ? body.schedule : {}));
    if (has('nightMode')) await setNightMode(body.nightMode);
    if (has('nightModeToggle') && !(await setPersonNightModeToggle(person, body.nightModeToggle))) await setNightModeToggle(body.nightModeToggle);
    if (has('sync')) await setSyncDefaults(body.sync);
    if (hasNetworkWaitKey) await setNetworkWait(body.networkWait);
    if (has('tagDimensions')) await asSettingsField('tagDimensions', () => setUserTagDimensions(body.tagDimensions));
    if (has('enforceTags')) await asSettingsField('enforceTags', () => setUserEnforceTags(body.enforceTags));
    // Live runs re-evaluate their open question against the new night settings.
    if (hasNightKey) for (const e of runs.values()) e.orch?.nightConfigChanged?.();
    if (hasActionsKey) { await setActionsSettings(body.actions); builtinsDetected = null; }   // re-detect the built-ins lazily
    if (hasBudgetKey) emitChanged('budget-changed');
    // Other open tabs repaint their Settings cards (a stale tab could otherwise
    // "save" its old checkbox state over this one with no feedback to either).
    if (hasSmartNaming || hasNamingModelKey) cachedPick = undefined;
    if (hasAskKey || hasAskWeb || hasSmartNaming || hasDebugSpawnKey || hasTitleModelKey || hasHideBuiltinKey || hasThemeKey || hasUiLevelKey || hasAutoKey || hasPrDescKey || hasAutoPrDescKey || hasHumanRateKey || hasMemoryDefragKey || hasAgentGenKey || hasNamingModelKey || hasCommandSummaryModelKey || hasWorkspaceScanKey || has('schedule') || has('sync') || has('tagDimensions') || has('enforceTags') || has('chat') || hasAskEngineKey || hasAskModelsKey || hasRequirementsInterviewKey || hasNetworkWaitKey || hasActionsKey || hasNightKey || hasRunEngineKey || hasStepModelsKey || hasModelRolesKey || hasUtilityModelsKey || hasUpdateCheckKey || hasKeepAwakeKey) emitChanged('settings-changed');
    // Editor / Terminal: saved as typed; a program Worca cannot find comes back as a warning on its field.
    const actionsWarnings = hasActionsKey ? Object.fromEntries(['editor', 'terminal']
      .map((k) => [k, launcherWarning(actionsSettings()[k], { findOnPath: (n) => findOnPath(n) })]).filter(([, w]) => w)) : null;
    return { actionsWarnings };
  }
}

// ---------------------------------------------------------------------------
// Feature flags (docs/feature-flags.md). GET lists every non-retiring flag; PATCH takes
// { key: true|false|null } (null = back to the default), applies `requires`, persists and
// broadcasts a `flags` frame (flagEvents above). 400 unknown key / bad value, 409 env-locked.
// ---------------------------------------------------------------------------
const flagsPayload = () => ({
  flags: listFlags().map((f) => ({ ...f, docsUrl: f.docs && APP_REPO_URL ? `${APP_REPO_URL}/blob/dev/${f.docs}` : null })),
});
app.get('/api/flags', (_req, res) => res.json(flagsPayload()));
app.patch('/api/flags', async (req, res) => {
  try {
    await setFlags(req.body);
    return res.json(flagsPayload());
  } catch (err) {
    if (err instanceof FlagError && err.code === 'locked') return res.status(409).json({ error: err.message, code: 'locked', key: err.key });
    if (err instanceof FlagError) return res.status(400).json({ error: err.message, ...(err.key ? { key: err.key } : {}) });
    return res.status(500).json({ error: err && err.message ? err.message : 'could not save the flags' });
  }
});

// ---------------------------------------------------------------------------
// Per-project model/effort config + custom-model registry. Validation lives in
// src/core/config.mjs; these routes are thin delegation (mirror /api/projects).
// ---------------------------------------------------------------------------
/** A project's night mode view: its own layer and the resolved config with per-field sources. */
function projectNightMode(projectDir) {
  return { project: readNightModePrefs(projectKey(projectDir)), ...effectiveNightConfig(projectDir) };
}

app.get('/api/config', async (req, res) => {
  const raw = req.query.projectDir;
  // No project selected yet (e.g. a fresh clone): still return the catalog so
  // the picker is never empty. The project-less catalog is predefined ⊕ GLOBAL
  // entries (the global catalog is project-independent by design §4.2); only
  // legacy per-project custom models need a projectDir.
  if (raw == null || raw === '') {
    return res.json({
      config: { steps: {}, customModels: [] },
      models: await listModels(''), steps: agentSteps(), efforts: EFFORTS,
      subagentModels: SUBAGENT_MODEL_VALUES,
    });
  }
  const projectDir = resolveProjectDir(raw);
  if (!projectDir) return badRequest(res, 'projectDir is required');
  try {
    // readRunConfig returns the full per-project config: legacy steps/customModels
    // PLUS the run-config workflows{} (node model/effort, feedback cycles) and
    // activeWorkflowId. It is a superset of readConfig, so the client keeps using
    // config.steps unchanged while gaining config.workflows / config.activeWorkflowId.
    // NOTE: readRunConfig forwards unknown extra keys verbatim — a project
    // configured under the REMOVED per-project guardrails model may still show
    // its raw legacy blob under config.guardrails. It is inert: nothing
    // interprets it (guardrails are selected per run via /api/guardrails).
    const [config, models] = await Promise.all([
      readRunConfig(projectDir), listModels(projectDir),
    ]);
    res.json({
      config, models, steps: agentSteps(), efforts: EFFORTS,
      // Night mode: the project's own layer plus what applies ({config, sources}) per field.
      // Beside `config`, not in it: clients assign `config` to their whole config state.
      nightMode: projectNightMode(projectDir),
      // The sub-agent model policy vocabulary is a FIXED alias enum (the CLI's Task
      // tool refuses catalog ids), so it ships beside `efforts` rather than being
      // derived from `models`.
      subagentModels: SUBAGENT_MODEL_VALUES,
    });
  } catch (err) {
    res.status(500).json({ error: err && err.message ? err.message : String(err) });
  }
});

app.post('/api/config', async (req, res) => {
  const body = req.body || {};
  const projectDir = resolveProjectDir(body.projectDir);
  if (!projectDir) return badRequest(res, 'projectDir is required');
  try {
    await setStep(projectDir, body.step, {
      model: body.model, effort: body.effort, fanOut: body.fanOut, askQuestions: body.askQuestions,
      subagentModel: body.subagentModel,
    });
    // Respond with the FULL run-config (mirrors PATCH): setStep's return value is
    // the legacy {steps, customModels} view only, and clients assign the response
    // to their whole config state — echoing the narrow view dropped workflows/
    // activeWorkflowId and made saved node models paint as unconfigured.
    const config = await readRunConfig(projectDir);
    res.json({ config });
  } catch (err) {
    // setStep throws only on validation (unknown step/model/effort) -> client error.
    return badRequest(res, err && err.message ? err.message : String(err));
  }
});

// ---------------------------------------------------------------------------
// PATCH /api/config -> write run-config: per-node model/effort, per-feedback
// cycle counts, and the active workflow id. Keyed by workflowId + node/feedback
// instance ids (see RunConfig in the design). Legacy per-role `steps` are
// written via POST /api/config and are left untouched here. setNodeModel now
// validates model/effort against the effective catalog exactly like setStep
// (configurable-models-design.md §4.5) -> 400; setFeedbackCycles still COERCES
// maxCycles to >= 1 (it never throws).
// body: { projectDir, workflowId, nodes?:{[id]:{model,effort}}, feedbacks?:{[id]:{maxCycles}}, wires?:{[wireId]:{maxCycles}}, activeWorkflowId?, humanInLoop? }
// ---------------------------------------------------------------------------
app.patch('/api/config', async (req, res) => {
  const body = req.body || {};
  const projectDir = resolveProjectDir(body.projectDir);
  if (!projectDir) return badRequest(res, 'projectDir is required');
  const workflowId = typeof body.workflowId === 'string' ? body.workflowId.trim() : '';
  // MAJ-1: every arm below keys a normalized table by workflowId, and
  // readWorkflowsMap rebuilds a map from those keys — an id like '__proto__'
  // used to be persisted unchecked and then broke readRunConfig for the whole
  // project. isSafeWorkflowId is the store's own id rule, so the API can never
  // write an id the store would refuse. (The recovery route DELETE
  // /api/config/workflow stays deliberately ungated: an already-poisoned row
  // must still be clearable.)
  const workflowIdError = (what) => {
    if (!workflowId) return `workflowId is required to set ${what} config`;
    if (!isSafeWorkflowId(workflowId)) return 'invalid workflowId';
    return null;
  };
  try {
    if (body.nodes && typeof body.nodes === 'object') {
      const bad = workflowIdError('node');
      if (bad) return badRequest(res, bad);
      for (const [nodeId, sel] of Object.entries(body.nodes)) {
        await setNodeModel(projectDir, workflowId, nodeId, {
          model: sel && sel.model, effort: sel && sel.effort,
          fanOut: sel && sel.fanOut, askQuestions: sel && sel.askQuestions,
          subagentModel: sel && sel.subagentModel,
        });
      }
    }
    if (body.feedbacks && typeof body.feedbacks === 'object') {
      const bad = workflowIdError('feedback');
      if (bad) return badRequest(res, bad);
      for (const [fbId, sel] of Object.entries(body.feedbacks)) {
        await setFeedbackCycles(projectDir, workflowId, fbId, sel && sel.maxCycles);
      }
    }
    if (body.wires && typeof body.wires === 'object') {
      const bad = workflowIdError('wire');
      if (bad) return badRequest(res, bad);
      for (const [wireId, sel] of Object.entries(body.wires)) {
        await setWireCycles(projectDir, workflowId, wireId, sel && sel.maxCycles);
      }
    }
    if (typeof body.activeWorkflowId === 'string' && body.activeWorkflowId.trim()) {
      const active = body.activeWorkflowId.trim();
      if (!isSafeWorkflowId(active)) return badRequest(res, 'invalid workflowId');
      await setActiveWorkflow(projectDir, active);
    }
    if (typeof body.humanInLoop === 'boolean') await setHumanInLoop(projectDir, body.humanInLoop);
    if (body.nightMode !== undefined) {
      // Night mode project layer (a patch; `null` resets to inherited). Validation errors → 400 below.
      writeNightModePrefs(projectKey(projectDir), body.nightMode);
      for (const e of runs.values()) if (e.projectDir === projectDir) e.orch?.nightConfigChanged?.();
    }
    const config = await readRunConfig(projectDir);
    res.json({ config, nightMode: projectNightMode(projectDir) });
  } catch (err) {
    // The config.mjs setters throw only on validation (unknown model/effort,
    // maxCycles < 1) -> client error, mirroring POST /api/config.
    return badRequest(res, err && err.message ? err.message : String(err));
  }
});

// ---------------------------------------------------------------------------
// DELETE /api/config/workflow -> "Reset to defaults" for one workflow in one
// project (newpipeline-ux-design.md §4.5). Drops every per-node/per-feedback
// override (and, for wf_default, the legacy per-role steps) so the accordion
// falls back to the workflow's defaults + the agent registry. Idempotent:
// resetting an already-clean project is a no-op 200.
// query: ?projectDir=&workflowId=
// ---------------------------------------------------------------------------
app.delete('/api/config/workflow', async (req, res) => {
  const projectDir = resolveProjectDir(req.query.projectDir);
  if (!projectDir) return badRequest(res, 'projectDir is required');
  const workflowId = typeof req.query.workflowId === 'string' ? req.query.workflowId.trim() : '';
  if (!workflowId) return badRequest(res, 'workflowId is required');
  try {
    await resetWorkflowConfig(projectDir, workflowId);
    res.json({ config: await readRunConfig(projectDir) });
  } catch (err) {
    res.status(500).json({ error: err && err.message ? err.message : String(err) });
  }
});

// POST /api/config/models (the per-project ADD) is deliberately GONE: new
// models are added to the GLOBAL catalog via POST /api/models (design §4.9 —
// the add flow moves entirely to the global Models view). DELETE stays so
// legacy per-project entries can still be cleaned up.
app.delete('/api/config/models', async (req, res) => {
  const projectDir = resolveProjectDir(req.query.projectDir);
  if (!projectDir) return badRequest(res, 'projectDir is required');
  const id = typeof req.query.id === 'string' ? req.query.id : '';
  if (!id.trim()) return badRequest(res, 'id is required');
  try {
    const config = await removeCustomModel(projectDir, id);
    res.json({ config, models: await listModels(projectDir) });
  } catch (err) {
    res.status(500).json({ error: err && err.message ? err.message : String(err) });
  }
});

// ---------------------------------------------------------------------------
// Global model catalog (configurable-models-design.md §4.10). Project-less by
// design — the catalog lives in ~/.worca-cc/settings.json (settings.mjs) and
// applies to every project. Env VALUES are secrets-adjacent: responses carry
// them MASKED (write-only editing; a whole-value ${VAR} ref is config, not a
// secret, and passes through readable), and a PATCH that echoes a masked value
// back means "keep" and is dropped from the write.
// ---------------------------------------------------------------------------

const maskEnvValue = (v) => (modelEnvRef(v) ? v : maskModelEnvValue(v));
// A bridged entry's `upstream.apiKey` is masked like an env secret; the rest of
// the block is routing config and passes through. `bridged`/`needsSignIn` are
// the picker/card facts (model-bridge-design.md §8.5), one readiness check
// per provider, key and base URL per response (an entry's own key or base URL
// can decide it, as in config.mjs composeCatalog).
const bridgeFacts = (m, readiness) => {
  if (!m.upstream) return {};
  const p = m.upstream.provider;
  const key = `${p}\n${m.upstream.apiKey || ''}\n${m.upstream.baseUrl || ''}`;
  if (!readiness.has(key)) readiness.set(key, providerReadiness(m.upstream));
  const r = readiness.get(key);
  return { bridged: p, needsSignIn: !r.ok, ...(r.ok ? {} : { signInReason: r.reason, signInMessage: r.message }) };
};
const maskedGlobalModel = (m, readiness = new Map()) => ({
  ...m,
  ...(m.env ? { env: Object.fromEntries(Object.entries(m.env).map(([k, v]) => [k, maskEnvValue(v)])) } : {}),
  ...(m.upstream ? { upstream: { ...m.upstream, ...(m.upstream.apiKey ? { apiKey: maskEnvValue(m.upstream.apiKey) } : {}) } } : {}),
  ...bridgeFacts(m, readiness),
});
const isMaskedEcho = (v) => typeof v === 'string' && v.startsWith('••');
const maskedGlobalModels = () => {
  const flagged = costUnreliableModelIds(); // §4.6 observed flag, merged for the editor's badge
  const readiness = new Map();
  return listGlobalModels().map((m) => ({
    ...maskedGlobalModel(m, readiness),
    ...(flagged.has(m.id.toLowerCase()) ? { costUnreliable: true } : {}),
  }));
};
/** A POST/PATCH `upstream` body with a masked apiKey echo dropped ("keep"). */
const upstreamInput = (u, current) => {
  if (!u || typeof u !== 'object' || Array.isArray(u)) return u;
  if (isMaskedEcho(u.apiKey)) {
    const keep = current && current.upstream ? current.upstream.apiKey : undefined;
    const { apiKey, ...rest } = u;
    return keep ? { ...rest, apiKey: keep } : rest;
  }
  return u;
};

/** Read-only plugin model entries (design §9.7): literals masked with the
 *  standard masker, ${VAR} refs readable, {secret} placeholders surfaced as
 *  display markers with their set-ness. */
const pluginModelsPayload = () => {
  const flagged = costUnreliableModelIds();
  const statusByPlugin = new Map();
  const readiness = new Map();
  return listPluginModels().map((m) => {
    if (!statusByPlugin.has(m.plugin)) statusByPlugin.set(m.plugin, pluginModelSecretStatus(m.plugin));
    const status = statusByPlugin.get(m.plugin);
    return {
      id: m.id, label: m.label, efforts: m.efforts, plugin: m.plugin,
      env: Object.fromEntries(Object.entries(m.env ?? {}).map(([k, v]) => [
        k, typeof v === 'string' ? maskEnvValue(v) : `(secret: ${v.secret})`,
      ])),
      secrets: status.filter((s) => m.secrets.includes(s.key)),
      ...(m.cost ? { cost: m.cost } : {}),   // manifest-pinned pricing — config, never a credential
      ...(m.upstream ? { upstream: { ...m.upstream } } : {}),   // a plugin apiKey is a ${VAR} ref by validation — readable
      ...bridgeFacts(m, readiness),
      ...(flagged.has(m.id.toLowerCase()) ? { costUnreliable: true } : {}),
    };
  });
};

app.get('/api/models', (req, res) => {
  const readiness = new Map();
  res.json({
    models: maskedGlobalModels(), plugin: pluginModelsPayload(), predefined: PREDEFINED_MODELS, efforts: EFFORTS,
    codex: CODEX_BUILTIN_MODELS, codexEfforts: CODEX_EFFORTS,   // §3.1a: the Codex built-ins group + the editor's Codex efforts
    copilot: COPILOT_BUILTIN_MODELS, copilotEfforts: COPILOT_EFFORTS,   // the Copilot built-ins group + the editor's Copilot efforts
    gooseEfforts: GOOSE_EFFORTS,                                 // GOOSE_THINKING_EFFORT values (no Goose built-ins)
    opencodeEfforts: OPENCODE_EFFORTS,                           // OpenCode's --variant values (no OpenCode built-ins)
    hideBuiltinModels: hideBuiltinModels(),   // the Models-view checkbox (#422)
    // Team policy catalog entries (team-policy design §8): read-only, env masked like a global's.
    policy: policyCatalogModels().map((m) => maskedGlobalModel(m, readiness)),
    providers: UPSTREAM_PROVIDERS,
  });
});

app.post('/api/models', async (req, res) => {
  const b = req.body || {};
  try {
    const model = await addGlobalModel({ id: b.id, label: b.label, efforts: b.efforts, env: b.env, cost: b.cost, upstream: upstreamInput(b.upstream), engine: b.engine });
    res.json({ model: maskedGlobalModel(model), models: maskedGlobalModels() });
  } catch (err) {
    // addGlobalModel throws only on validation (empty/dup id, unknown effort,
    // reserved env key, non-string env value, malformed upstream) -> client error.
    return badRequest(res, err && err.message ? err.message : String(err));
  }
});

// ---------------------------------------------------------------------------
// Providers + the Copilot import (model-bridge-design.md §9). Never a token in
// a response; the sign-in is a device-flow session the client polls.
// ---------------------------------------------------------------------------
const providerError = (res, err) => {
  const msg = err && err.message ? err.message : String(err);
  if (err && (err.code === 'TERMS' || err.code === 'NOT_SIGNED_IN')) return res.status(409).json({ error: msg, code: err.code });
  return badRequest(res, msg);
};

// ── Ask Worca voice mode (docs/speech.md) ──
// Behind the same global loopback / identity-proxy guards as every /api/ask
// route (:1131, :1144). They name no thread, so the thread-owner guard (:1181)
// has nothing to check. Registered before /api/providers/:name so the param
// routes never see "speech".
const speechFail = (res, err) => res.status(err && err.status ? err.status : 502).json({ error: err && err.message ? err.message : String(err) });

app.get('/api/speech', (_req, res) => {
  // downloaded: the voice chip says "Downloading…" only when the models really are fetched.
  let downloaded = { stt: false, tts: false };
  try { downloaded = speechAssetStore().downloaded(); } catch { /* no worca home: nothing downloaded */ }
  res.json({ ...speechState(), downloaded });
});

app.patch('/api/providers/speech', async (req, res) => {
  try {
    await patchSpeech(req.body || {});
    emitChanged('settings-changed');
    res.json(await providersState());
  } catch (err) {
    return providerError(res, err);
  }
});

// Providers › Speech: "Remove speech models" (the size shows on the card).
app.delete('/api/speech/cache', async (_req, res) => {
  try {
    const bytes = speechAssetStore().clear();
    res.json({ removed: bytes, providers: await providersState() });
  } catch (err) {
    res.status(err && err.status === 409 ? 409 : 500).json({ error: err && err.message ? err.message : String(err) });
  }
});

